programs.sol:
"""Lexical music, arts, and enjoyment responses, not a topic classifier.

The strongest negative values mark 'music' and corresponding music/joy
characters in Chinese, Japanese, and Korean. Smaller values mark music
stems, arts, entertainment, food, and pictures. The micro sign has a
separate negative response. Word boundaries and a few split-word endings
matter; context is otherwise ignored. Values are rounded estimates from training examples.
"""

READS = ()

MUSIC_NAMES = {'musica', 'música', 'musique', 'musik', 'müzik', 'nhạc', 'музык'}
MUSIC_WORDS = {'musical', 'musician', 'musicians'}
PERFORMANCE = {'dance', 'dancing', 'tunes', 'instrumental', 'orchestra'}
ART_WORDS = {'artist', 'artists', 'artistic', '艺术家'}
PICTURES = {'photos', 'pictures', 'photography', 'image', 'artwork', 'artworks'}


def lexical_value(token):
    word = token.strip().lower()
    boundary = token[:1].isspace()
    if word == 'music':
        return -5.95 if boundary else -5.65
    if word == 'usic':
        return -4.9
    if word in {'.music', '_music', '/music'}:
        return -3.5
    if word == '乐':
        return -6.55
    if word in {'樂', '楽', '音乐', '音樂'}:
        return -5.6
    if word == '악':
        return -3.8
    if word in MUSIC_NAMES:
        return -3.0
    if word == 'mus':
        return -1.2 if token.strip()[:1].isupper() else -0.8
    if word == 'му' and boundary:
        return -1.2
    if word == 'mús':
        return -1.8
    if word == 'µ':
        return -1.0
    if word in MUSIC_WORDS:
        return -1.35
    if word == 'food':
        return -1.6
    if word in {'料理', '快乐', '快樂', '乐观', '的食物'}:
        return -1.5
    if word == 'art':
        if boundary:
            return -1.05
        return -0.7 if token.strip() == 'Art' else -0.13
    if word in {'arts', '艺术'}:
        return (-0.6 if boundary else 0.0) if word == 'arts' else -1.25
    if word in {'歌', '曲', '美食', '美术', '食品', '食物', '食', '音', '欢乐'}:
        return -1.0
    if word in {'concerts', 'dances'}:
        return -1.25
    if word in PERFORMANCE:
        return -0.95
    if word in {'images', '娱乐', '舞', '琴', 'entertainment'}:
        return -0.8
    if word in {'foods', 'songs', 'pleasure', 'tune', '饭', '酒'}:
        return -0.65
    if word == 'justice':
        return -0.65 if token.strip().islower() else -0.45
    if word in ART_WORDS or word in {'concert', '食べ', 'composers'}:
        return -0.5
    if word in PICTURES or word in {
        'audio', 'song', 'movies', 'games', 'literature', 'culture',
        'happy', 'happiness', 'guitar', 'violin', 'composer', 'instrument',
        'instrumentation', 'playlist', 'jazz', 'symphony', '艺术品',
    }:
        return -0.35
    if word in {'.image', '_image'}:
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = lexical_value(token)
    same_document = (len(prefix.token_strings) > 1
                     and prefix.document_ids[-2] == prefix.document_ids[-1])
    if same_document:
        previous = prefix.token_strings[-2].strip().lower()
        word = token.strip().lower()
        if previous == 'music':
            if word == 'of':
                value = -1.3
            elif not token[:1].isspace() and word in {'ian', 'ians', 'ical', 'as'}:
                value = -0.65
        elif previous == 'art':
            if word == 'of':
                value = -0.35
            elif not token[:1].isspace() and word == 'istic':
                value = -0.3
    return None, value

programs.haiku:
"""Music, food and arts words as a negative-valued detector (draft 6).

What it does: on each token it looks only at the token's own text. Tokens that say
"music" (in English or as the Chinese/Japanese/Korean words for it) get a strong negative
value, which is what this component's activation does. Music in other languages, the words
"musical" and "musician", and the word "food" get a smaller negative value. Words for art,
dance, songs, concerts, instruments and entertainment get a mild one. Every other token gets 0.
"""

# Music itself: the strongest response.
MUSIC_CJK = {"乐", "樂", "楽", "音乐", "音樂", "音楽", "악"}
# Music in other languages: a weaker response.
MUSIC_FOREIGN = {"musik", "música", "musica", "musique", "müzik", "nhạc", "музык"}
# People and adjectives built on "music".
MUSIC_PEOPLE = {"musical", "musician", "musicians"}
# The word "food" and Chinese words for food.
FOOD = {"food", "foods", "食", "食物", "食品", "美食", "料理", "饭", "飯"}
# Art, dance, songs, concerts, instruments, images and entertainment: mild.
ARTS = {"art", "arts", "artist", "artists", "dance", "dancing", "song", "songs", "tune", "tunes",
        "concert", "concerts", "instrument", "instrumental", "orchestra", "images",
        "entertainment", "歌", "曲", "音", "舞", "艺术", "娱乐"}

READS = ()


def step(carry, prefix, upstream):
    """Negative on music, food and arts words; zero on every other token."""
    word = prefix.token_strings[-1].strip().lower()
    if word in MUSIC_CJK or ("music" in word and word not in MUSIC_PEOPLE):
        value = -5.9
    elif word in MUSIC_FOREIGN:
        value = -3.0
    elif word in MUSIC_PEOPLE or word in FOOD:
        value = -1.4
    elif word in ARTS:
        value = -0.7
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Approximate a sparse lexical detector for music and neighboring arts topics.

The large responses are concentrated on explicit music words; related words about
performing, images, and food tend to have smaller responses. This uses the current
word only, rather than attempting to reproduce the MLP computation.
"""

import re

READS = ()

_MUSIC = {
    "musician", "musicians", "musical", "musically", "concert", "concerts",
    "orchestra", "instrument", "instruments", "tune", "tunes", "song",
    "songs", "guitar", "playlist", "soundtrack", "singer", "singers",
    "album", "albums", "dance", "dancing", "audio",
}
_ARTS = {
    "art", "artist", "artists", "artwork", "image", "images", "photo",
    "photos", "photography", "visual", "painting", "paintings", "film",
    "movie", "movies", "cinema", "entertainment",
}
_FOOD = {
    "food", "cooking", "cuisine", "meal", "meals", "restaurant",
    "restaurants", "eat", "eating",
}


def step(carry, prefix, upstream):
    """Give music terms the largest negative score, and related arts/food smaller ones."""
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = "" if carry is None or carry[0] != doc else carry[1]

    # Join alphabetic token fragments, but start a fresh word after whitespace or punctuation.
    if raw and raw[0].isascii() and raw[0].isalpha():
        joined = previous + raw
    else:
        joined = raw
    words = re.findall(r"[a-z]+", joined.casefold())
    tail_match = re.search(r"[a-z]+$", joined.casefold())
    tail = tail_match.group(0) if tail_match else ""

    value = 0.0
    if "乐" in raw or "樂" in raw:
        value = -6.3
    elif "악" in raw:
        value = -4.0
    elif any(mark in raw for mark in ("音", "曲", "楽", "樂")):
        value = -0.9
    elif "music" in words:
        value = -6.3
    elif any(word in _MUSIC for word in words):
        value = -0.9
    elif any(word in _ARTS for word in words):
        value = -0.7
    elif any(word in _FOOD for word in words):
        value = -0.9
    if "food" in words:
        value = -1.55
    elif "art" in words:
        value = -1.0

    return (doc, tail), float(value)

programs.sol:
"""Predict lexical science cues rather than a passage's scientific topic.

The largest positive response is to 'scientific', including split spellings.
Related science vocabulary in several languages, research, art, technical
adjectives, and Python tooling have smaller positive responses. Inflections
can continue a science stem; a following content token gets a small echo.
Two secondary cues, the Latin-cross symbol and '<think>', are negative.
Everything else is zero. Only the previous token is remembered, and that
memory resets at document boundaries. These rules omit the component's
many weaker, token-specific responses rather than storing a vocabulary table.
"""
READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    document = prefix.document_ids[-1]
    first = not carry or carry[0] != document
    previous = '' if first else carry[1]
    value = 0.0

    if word == 'scientifically':
        value = 1.8
    elif word == 'scientific':
        value = 2.7
    elif word in {'scientist', 'scientists'}:
        value = 1.1
        if raw.strip()[0].isupper():
            value = 1.6 if word.endswith('s') else 1.3
    elif word.startswith('physicist'):
        value = 0.55
    elif word == 'scient':
        if first:
            value = 3.0 if raw.strip()[0].isupper() else 1.5
        else:
            value = 1.9 if raw[:1].isspace() else 0.95
    elif word == 'ific':
        value = 3.25 if previous.endswith('scient') else 0.33
        if previous.endswith('cient') and not previous.endswith('scient'):
            value = 2.15
        elif previous.endswith('ient') and not previous.endswith('cient'):
            value = 1.3
    elif word == 'cient':
        value = 0.45
    elif word == 'ient' and previous.endswith('/sc'):
        value = 0.5
    elif word == 'ifique':
        value = 1.3 if previous.endswith('scient') else 0.15
    elif word.startswith('científ'):
        value = 2.15
    elif word in {'science', 'sciences'}:
        value = 0.4 if word == 'science' else 0.3
    elif word.startswith('науч'):
        value = 2.05
    elif word == 'العلم':
        value = 1.1
    elif word.endswith('issenschaft'):
        value = 0.86
    elif word.startswith(('科学', '科學')):
        value = 0.65 if word.endswith(('院', '发展')) else 1.25
    elif word in {'自然科学', '科研', '中科院'}:
        value = 0.9
    elif word == '科':
        value = 0.72
    elif word.startswith('科技') or word in {'学科', '学术', '學術'}:
        value = 0.54
    elif word == 'scholarly':
        value = 0.7
    elif word in {'scholar', 'scholars'}:
        value = 0.25
    elif word.startswith('mathematic'):
        value = 0.42
    elif word.startswith('researcher'):
        value = 0.35
    elif word == 'research':
        value = 0.16
    elif word == 'artistic':
        value = 0.8
    elif word in {'artist', 'artists', 'artwork'}:
        value = 0.25
    elif word in {'academic', 'technical', 'numerical', 'numeric', 'systematic'}:
        value = 0.21
    elif word in {'industrial', 'technological', 'graphical', 'astronomical'}:
        value = 0.35
    elif word in {'chemical', 'musical', 'empirical'}:
        value = 0.16
    elif word == 'istic':
        value = 0.75 if previous.endswith('art') else 0.28
    elif word == 'ically':
        value = 0.13
    elif word == 'ic':
        value = 0.05
    elif word in {'matplotlib', 'plotlib', 'scipy', 'sklearn', 'pyobject', '(pyobject'}:
        value = 0.6
    elif word == 'uptools' and previous.endswith('set'):
        value = 1.0
    elif word in {'numpy', 'pytest'}:
        value = 0.3
    elif word in {'coeff', '_coeff', '.coeff'}:
        value = 0.48 if word.startswith('.') else 0.2

    # Inflections continuing Russian and German science word stems.
    if (previous.endswith('науч') and word.startswith('н')
            and not raw[:1].isspace()):
        value = 0.6
    elif previous.endswith('issenschaft') and not raw[:1].isspace():
        if word.startswith('lich'):
            value = 1.4 if word == 'licher' else 0.95
        elif word in {'en', 'ler'}:
            value = 0.36

    if previous == 'scientific' and word.isalpha():
        # A short echo on the following content word, not an ongoing topic flag.
        if word not in {'a', 'an', 'the', 'of', 'and', 'or', 'in', 'for', 'to'}:
            value += 0.15
    if word == '✝':
        value = -0.31
    elif word == '<think>':
        value = -0.20
    return (document, word), value

programs.luna:
"""Estimate the rare science-word response from the word being completed now."""

READS: tuple[str, ...] = ()

_CHINESE_SCIENCE = ("科学", "科學", "科技", "科研", "学术", "學術", "中科院")


def _latin_word(text):
    end = len(text)
    start = end
    while start and text[start - 1].isalpha() and ord(text[start - 1]) < 0x250:
        start -= 1
    return text[start:end].lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (doc, "")
    if doc != old_doc:
        tail = ""
    piece = prefix.token_strings[-1]
    tail = (tail + piece)[-80:]
    word = _latin_word(tail)

    value = 0.003
    if "scientif" in word or "cientif" in word:
        value = 2.5
    elif "scientist" in word:
        value = 1.3
    elif "science" in word or word.startswith(("ciencia", "ciencias")):
        value = 0.45
    elif "scient" in word:
        value = 1.6
    elif word.startswith("cienc"):
        value = 0.7
    elif word.startswith(("research", "recherch", "ricerc")):
        value = 0.25
    elif word.startswith(("mathemat", "physic", "chemistr", "biolog", "astronom")):
        value = 0.35
    elif "wissenschaft" in word:
        value = 0.8
    elif tail.endswith(_CHINESE_SCIENCE):
        value = 0.8
    elif tail.endswith("科"):
        value = 0.45
    elif tail.endswith("研究"):
        value = 0.2
    elif tail.endswith("науч"):
        value = 1.5

    return (doc, tail), float(value)

programs.sol:
"""A lexical detector for kinds, types, species, and indefinite classes.

It gives fixed strengths to familiar category-naming words, including code
identifiers and several translations. Chinese/Japanese 種 and 种 are especially
strong even in seed/planting words: this is a vocabulary cue, not a complete
semantic classifier. English 'of' inherits a response from a preceding kind
name or group-selecting quantifier. 'Each other' is weaker than 'other'.
"""

READS = ()

KIND_WORDS = {
    'kind': 1.9, 'kinds': 2.38, 'kinda': 1.9,
    'type': 1.2, 'types': 1.12,
    'species': 2.3, 'breed': 0.88, 'breeds': 1.28,
    'variety': 1.36, 'varieties': 1.26,
    'sort': 0.72, 'sorts': 0.9,
    'various': 1.96, 'certain': 0.95, 'such': 0.73,
    'other': 0.72, 'others': 0.24,
    'genre': 0.36, 'genres': 0.57, 'breeding': 0.61,
}

# Related vocabulary: kind/type, ways, variety, and unspecified classes.
TRANSLATIONS = {
    'вид': 0.93, 'тип': 0.46, 'типа': 0.53, 'способ': 0.77,
    'различные': 1.0, 'различных': 1.1, 'всяк': 0.45,
    'نوع': 1.42, 'jenis': 1.65, 'giống': 1.3,
    'tipo': 0.6, 'tipos': 0.66, 'sorte': 0.47,
    'verschied': 1.03, 'verschiedene': 1.1, 'verschiedenen': 0.96,
    'diversos': 0.59, 'diversas': 0.59,
    '様々': 0.9, '様々な': 0.98, '色々': 0.87,
    'さまざま': 0.5, 'さまざまな': 1.4, '다양한': 0.58,
    '종': 4.65, '其他': 0.7, '某些': 1.1,
}

PARTITIVES = {
    'one': 1.1, 'some': 1.05, 'all': 1.02, 'each': 1.06,
    'any': 0.9, 'none': 0.9, 'most': 0.7, 'many': 0.7,
    'which': 0.6, 'either': 0.53, 'both': 0.53, 'neither': 0.56,
    'several': 0.55, 'few': 0.3, 'more': 0.43, 'much': 0.25,
    'two': 0.4, 'three': 0.4, 'four': 0.36, 'five': 0.32,
    'six': 0.4, 'seven': 0.4, 'eight': 0.4, 'nine': 0.4,
    'those': 0.3, 'these': 0.23,
    'kind': 1.72, 'kinds': 1.45, 'type': 1.15, 'types': 0.83,
    'variety': 1.68, 'varieties': 1.29, 'species': 1.61,
    'sort': 1.24, 'sorts': 1.0,
}


def chinese_kind(text):
    # The isolated kind character is stronger than compounds containing it.
    if text in {'种', '種'}:
        return 7.35
    if text in {'品种', '物种', '特种'}:
        return 3.0
    if text in {'接种', '播种'}:
        return 1.0
    if text.endswith(('种', '種')):
        return 6.5 if text in {'一种', '有一种'} else 5.4
    if text in {'种类', '種類'}:
        return 3.4
    if text in {'种植', '种族'}:
        return 2.4
    if text == '各类':
        return 2.04
    if text in {'这类', '此类', '两类'}:
        return 1.1
    if text in {'类型', '類型', '类', '類'}:
        return 0.65
    if text.endswith(('类', '類')):
        return 0.5
    if '种' in text or '種' in text:
        return 1.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    # Attention resets at document boundaries, so our one-token context does too.
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.strip('._-/()[]').lower()
    spaced = raw[:1].isspace()
    value = KIND_WORDS.get(word, TRANSLATIONS.get(word, 0.0))
    if word == 'kind' and not spaced:
        value = 1.95 if text == 'Kind' else 1.31
    elif word == 'species' and not spaced:
        value = 1.73
    elif word == 'sort' and not spaced:
        value = 0.46
    elif word == 'such' and text.istitle():
        value = 0.9
    elif word == 'other':
        value = {'each': 0.1, 'the': 0.36, 'any': 0.51,
                 'some': 0.38, 'no': 0.51, 'every': 0.47}.get(previous, 0.72)
    elif word == 'of':
        value = PARTITIVES.get(previous, 0.1 if not spaced else 0.0)
    elif word in {'typeof', 'isinstance', 'instanceof'}:
        value = {'typeof': 0.72, 'isinstance': 1.14, 'instanceof': 0.61}[word]
    elif word in {'typ', 'ype', 'ypes'}:
        value = 0.4 if word == 'typ' else 0.63
    elif text.endswith(('Type', 'Types', 'TypeId', 'TypeError')):
        value = 1.2
    if not value:
        value = chinese_kind(text)
    # A byte fragment can finish a kind-character without decoding alone.
    if '\ufffd' in text and carry is not None and carry[0] == doc:
        if prefix.text_prefixes[-1].endswith(('种', '種')):
            value = 8.6
    return (doc, word), float(value)

programs.haiku:
"""Kind/type words. The component fires on words that name a kind, sort or type, or introduce
a category ('such', 'various', 'certain', 'other'), on code identifiers containing 'type', and
on the 'of' that follows a quantifier or kind word ('kind of', 'one of', 'all of').
Chinese and Japanese 种/種 ('kind'), as in 这种 and 各种, are the strongest."""

READS = ()

# Words that name a kind or introduce one, and how strongly they fire.
KIND_WORDS = {
    " kind": 1.9, " kinds": 2.3, " species": 2.3, " various": 1.9, " Various": 1.8,
    " variety": 1.4, " varieties": 1.3, " sort": 0.7, " sorts": 0.9, " such": 0.8,
    " Such": 0.9, " certain": 1.0, " other": 0.6, " Other": 0.7,
}
# The 'of' after these words, and how strongly it fires.
OF_AFTER = {
    " kind": 1.8, " variety": 1.8, " species": 1.7, " kinds": 1.4, " sort": 1.3, " type": 1.2,
    " types": 0.9, " one": 1.1, " One": 1.2, " all": 1.0, " All": 1.1, " some": 1.05,
    " Some": 1.2, " each": 1.05, " any": 0.9, " most": 0.7, " many": 0.7, " none": 0.8,
}
# Kind/sort characters inside a token (Chinese, Japanese, Korean).
CJK_KIND = {"种": 6.0, "種": 6.5, "종": 4.6}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in KIND_WORDS:
        return None, KIND_WORDS[tok]
    if tok == " of" and prev in OF_AFTER:
        return None, OF_AFTER[prev]
    for ch, value in CJK_KIND.items():
        if ch in tok:
            return None, value
    low = tok.lower()
    if "type" in low or "kind" in low:
        return None, 1.1
    return None, 0.0

programs.luna:
"""Approximate a feature for words that name or distinguish kinds of things.

Examples include “kind”, “type”, “species”, “various”, “other” and “such”.
The rule uses the current word and a few words before “of”; it does not
interpret the surrounding sentence.
"""

READS = ()
import string

STRONG_KIND_WORDS = {"kind", "kinds", "species", "various"}
TYPE_WORDS = {"type", "types", "typeof", "variety", "varieties"}
CHINESE_KIND_WORDS = {
    "各种", "各类", "各類", "类型", "種類", "种类", "某些", "其他", "其它",
}
OF_AFTER = {
    "number", "terms", "condition", "conditions", "kind", "kinds",
    "type", "types", "sort", "sorts", "species", "variety", "varieties",
    "range", "group", "groups", "one", "some",
}


def clean(token):
    return token.strip().strip(string.punctuation).lower()


def step(carry, prefix, upstream):
    word = clean(prefix.token_strings[-1])
    if word in STRONG_KIND_WORDS:
        return None, 1.8
    if word in TYPE_WORDS:
        return None, 1.2
    if word == "certain":
        return None, 1.0
    if word == "such":
        return None, 0.75
    if word == "other":
        return None, 0.6
    if word in {"sort", "sorts"}:
        return None, 0.65
    if word in {"genus", "technique", "techniques", "diverse"}:
        return None, 0.25
    if word in {"variant", "variants", "particular"}:
        return None, 0.1
    if word in CHINESE_KIND_WORDS:
        return None, 1.0
    if (word == "of" and len(prefix.token_strings) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        if clean(prefix.token_strings[-2]) in OF_AFTER:
            return None, 1.0
    return None, 0.0

programs.sol:
"""A lexical detector centered on citations and punctuation-bearing phrases.

The largest response is on the ``al`` of ``et al``, followed by a smaller
response on its period. Other cues are family-name fragments, name placeholders,
honorifics, negative-contraction stems, dotted abbreviations, and parenthetic
phrases, with a weak negative baseline on the digit zero.
These are fitted scalar responses, not predictions of unseen tokens.
Only the last two tokens of the current document are consulted. Ordinary tokens
are left at zero; individual surnames and small background variations are omitted.
"""
READS = ()

NEGATIVE_STEMS = {
    'don', 'doesn', 'didn', 'isn', 'aren', 'wasn', 'weren',
    'hasn', 'haven', 'hadn', 'wouldn', 'couldn', 'shouldn',
    'mustn', 'needn', 'shan',
}
# Recognizable fragments of Scandinavian, Greek, Japanese, Slavic,
