    'amura': 3.6, 'amoto': 3.2, 'imoto': 2.5,
    'ashi': 0.7, 'uchi': 0.9, 'awa': 0.55,
    'owski': 2.1, 'owitz': 2.2, 'ovic': 1.8, 'ovich': 1.1,
    'inski': 1.25, 'insky': 1.0, 'ski': 0.8, 'kov': 0.55,
