"""Layer-0 MLP unit 771: a detector for the abbreviation "al" of the citation "et al."

Its strongest response is on " al" right after " et" (as in "Sakai et al."). The period or
comma that closes the citation fires more weakly. Smaller responses come from a few other
abbreviated or split tokens: "e.g." and "i.e.", "U.S.", titles (Mr, Mrs, Dr), the stem of a
negative contraction (don, doesn, isn ... before "'t"), the placeholder NAME, and the "sson"
of a surname such as Karlsson. Everything else is predicted as 0. Each value reads only the
newest token and the one before it, so the rule is causal.
"""

READS = ()

NEGATION_STEMS = {"don", "doesn", "didn", "isn", "aren", "wasn", "weren", "haven", "hasn", "couldn", "wouldn", "shouldn", "won"}
TITLES = {"Mr", "Mrs", "Dr"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    word = cur.strip()
    if cur == " al" and prev == " et":
        value = 15.0
    elif cur in (".", ".,") and prev == " al":
        value = 3.0
    elif cur == "sson":
        value = 5.0
    elif cur == ".g" and prev == "e":
        value = 1.4
    elif cur == ".e" and prev == "i":
        value = 1.0
    elif word == "NAME":
        value = 1.5
    elif word in TITLES:
        value = 0.8
    elif word in NEGATION_STEMS:
        value = 0.7
    else:
        value = 0.0
    return None, value

programs.luna:
"""A mean baseline with small lexical rules for some rare responses.

The cues are subject-plus-contraction stems, titles, “for example/instance”,
the phrase “other hand”, a placeholder name, and a letter inside an abbreviation.
Every other position receives the component's average activation.
"""

READS = ()

CONTRACTION_STEMS = {"don", "doesn", "aren", "isn", "haven"}
SUBJECTS = {"i", "you", "he", "she", "it", "we", "they", "this", "that", "which"}
HONORIFICS = {"mr", "mrs", "ms", "dr"}
EXAMPLE_CUES = {"example", "instance"}
MEAN_ACTIVATION = 0.00458


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip()
    prior = previous.lower().strip(".,;:!?\"'")

    value = MEAN_ACTIVATION
    if raw[:1].isspace() and word in CONTRACTION_STEMS:
        if prior in SUBJECTS or previous[:1].isupper():
            value = 0.68
    elif raw[:1].isspace() and word in HONORIFICS:
        value = 0.88
    elif word in EXAMPLE_CUES and prior == "for":
        value = 0.90
    elif token == "NAME":
        value = 1.0
    elif word == "hand" and prior == "other":
        value = 0.90
    elif (
        len(token) == 2
        and token[0] == "."
        and token[1].isalpha()
        and len(previous) == 1
        and previous.isalpha()
    ):
        value = 0.78
    return None, value

programs.sol:
"""A weak mixture of lexical preferences and word-boundary effects.

The lexical rules describe small English word classes, not a single semantic
feature: universal person/thing pronouns are especially positive; absolute
frequency words, polarity labels, and third-person possessives are negative.
Capitalized pieces continuing a word or identifier get a negative offset.
Chinese text has a small boundary-dependent offset. All adjustments are small
except the rare lexical responses. Position is counted within each document;
the background is slightly more negative early on. These rules leave most
token-specific variation unexplained.
"""
import unicodedata

READS = ()

# Each row is a recognizable word class, with a fitted activation offset.
WORD_GROUPS = (
    ({'someone', 'somebody', 'anyone', 'anybody'}, 0.033),
    ({'something', 'anything'}, -0.021),
    ({'nothing'}, -0.076),
    ({'often', 'sometimes', 'generally', 'usually'}, 0.040),
    ({'currently', 'recently'}, 0.082),
    ({'entire', 'complete', 'whole', 'overall'}, 0.049),
    ({'his', 'their'}, -0.029),
    ({'him', 'them'}, 0.035),
    ({'positive', 'negative'}, -0.070),
    ({'possible', 'impossible'}, -0.037),
    ({'about', 'between'}, -0.030),
    ({'near', 'beyond'}, 0.078),
    ({'during'}, 0.053),
    ({'all', 'each', 'every'}, -0.007),
)
LEXICAL = {word: value for words, value in WORD_GROUPS for word in words}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    word, before = token.strip(), previous.strip()
    lower = word.lower()
    chinese = any('\u4e00' <= c <= '\u9fff' for c in word)
    prev_chinese = any('\u4e00' <= c <= '\u9fff' for c in before)
    value = -0.001

    if len(word) > 5:
        value -= 0.0025
    if word.istitle() and not word.isupper():
        if before.isalpha():
            value -= 0.0065 if token[0].isspace() else 0.029
        else:
            value += 0.002
    if word.isupper() and before.isalpha() and not before.isupper():
        value -= 0.012
    if (word.isascii() and word.isalpha()
            and not (word.islower() or word.isupper() or word.istitle())):
        value -= 0.022
    if chinese:
        if prev_chinese:
            value -= 0.008
        elif before and all(unicodedata.category(c).startswith('P') for c in before):
            value += 0.014
    elif prev_chinese:
        value -= 0.0035

    value += LEXICAL.get(lower, 0.0)
    if lower in {'everyone', 'everybody', 'everything'}:
        value += 0.208 if word.islower() else 0.081
    elif lower in {'always', 'never', 'ever'}:
        value -= 0.057 if word.islower() else 0.026
    elif lower in {'thus', 'therefore', 'hence'} and word.islower():
        value -= 0.050
    elif lower in {'however', 'nevertheless', 'nonetheless'}:
        value += -0.024 if word.islower() else 0.022

    if not word or word.isdecimal():
        value += 0.001
    if '\n' in token:
        value += 0.0024
    if position < 32:
        value -= 0.0038
    elif position < 128:
        value -= 0.0014
    return (doc, token, position), float(value)

"""A sparse lexical feature for cutting/slicing, strongest on the character 切.

The same character also occurs in words for everything, closeness, and
importance. Whole compounds have different response sizes; long compounds
and names are usually much weaker. English cut/slice forms respond about
one fifth as strongly. A few totality/emphasis words also respond.
Other tokens are zero. This approximates the large lexical responses,
not the component's many small background fluctuations.
"""

READS = ()


def lexical_value(text):
    word = text.strip('._-').lower()
    if text in {'切', '一切'}:
        return 5.8
    if '切' in text:
        if text == '的一切':
            return 5.0
        if text == '这一切':
            return 4.2
        if text.startswith('一切都'):
            return 3.2
        if text in {'切实', '深切'}:
            return 3.6
        if text in {'切り', '切成'}:
            return 2.9
        if text in {'密切', '切入', '切断', '大切', '迫切'}:
            return 2.3
        if text in {'切割', '切除', '真切', '切入点'}:
            return 1.9
        if text in {'切换', '亲切'}:
            return 1.5
        if text in {'切れ', '关切', '确切'}:
            return 0.9
        if text == '切尔':
            return 0.5
        return 0.3 if len(text) > 2 else 2.3
    if word in {'cut', 'cuts', 'cutting', 'slice', 'slices', 'slicing'}:
        return 1.15 if text != 'Cutting' else 1.55
    if word == 'sliced':
        return 0.8
    if word in {'blade', 'cutter', 'cutoff', 'keen', 'slic'}:
        return 0.55
    if text in {'割', '刀', '剪'}:
        return 0.65
    if text in {'根本', '永远', '尽量', '千万'}:
        return 0.75
    if text in {'彻底', '深刻'}:
        return 0.55
    if text in {'すべて', '全て', 'mọi', 'çok'}:
        return 0.8
    if text == 'thiết':
        return 1.55
    if text.lower() in {'все', 'всё'}:
        return 0.55
    if word == 'everything':
        return 0.23
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    raw = prefix.token_strings[-1]
    text = raw.strip()
    # A split UTF-8 token can complete 切 despite decoding alone as U+FFFD.
    if '\ufffd' in text and previous:
        if prefix.text_prefixes[-1].endswith('切'):
            text = '切'
    value = lexical_value(text)
    # 適切 (appropriate) is weaker even when split between two tokens.
    if text == '切' and previous.endswith('適'):
        value = 4.0
    return (document, (previous + raw)[-8:]), value

programs.haiku:
"""Cutting / 切 detector (layer-0 MLP feature, down_proj unit 774).

The unit fires on the token itself, mostly with no need for context:
  * the Chinese character 切 (qiē: cut, close, earnest) and the word 一切 ('everything'):
    the strongest triggers (about 6). Other words built on 切 (切实, 深切, 大切, 切断, 切り) ~3.
  * English cutting words: cut, cuts, cutting, cutter, slice, slices, slicing, sliced, blade (~1.2).
  * weaker (~0.5-0.9): knife/cut characters 刀 割 剪, and the 'all' words все, всё, すべて, mọi.
Otherwise it predicts 0. Matching ignores punctuation, so '.slice' and '_cut' count as 'slice'/'cut'.
"""

import re

CUT_EN = {"cut", "cuts", "cutting", "cutter", "slice", "slices", "slicing", "sliced", "blade"}
KNIFE_ZH = {"刀", "割", "剪"}
ALL_WORDS = {"все", "всё", "すべて", "mọi"}

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = re.sub(r"[^a-z]", "", tok.lower())
    if tok.strip() in ("切", "一切"):
        return None, 6.0
    if "切" in tok:
        return None, 3.0
    if "一切" in tok:
        return None, 5.0
    if word in CUT_EN:
        return None, 1.2
    if tok.strip() in KNIFE_ZH or tok.strip().lower() in ALL_WORDS:
        return None, 0.6
    return None, 0.0

programs.luna:
"""A small lexical proxy for sparse totality and cutting responses."""
import re

READS: tuple[str, ...] = ()

TOTALITY = re.compile(
    r"(?<![a-z])(?:all|every|everything|whole|entire)(?![a-z])"
)
CUTTING = re.compile(r"(?<![a-z])(?:cut|slic|chop|blade)[a-z]*(?![a-z])")


def step(carry, prefix, upstream):
    """Use the current token's spelling to predict a few recurring responses."""
    word = prefix.token_strings[-1].lower()
    if TOTALITY.search(word) or any(
        part in word
        for part in ("все", "всё", "一切", "所有", "全部", "すべて", "全て", "mọi")
    ):
        return None, 0.21
    if CUTTING.search(word) or "切" in word or "割" in word:
        return None, 0.30
    return None, 0.00288

programs.sol:
"""Predict double-quotation punctuation, weakened by recent quotation marks.

ASCII and curly double quotes usually give negative estimates. Attached
punctuation and typographic style set their strength. A recent quote and a dense run of
quotes attenuate the response, as does the document's first token. Escaped
quotes and quotes fused to words leave a weaker trace. Other text is silent,
except doubled backslashes, which make a small positive contribution.
"""
import math

READS = ()
QUOTES = frozenset('"“”„«»「」『』″')


def strength(s):
    # Return the isolated response and how much recent quotes can weaken it.
    if '"' in s:
        before, after = s.split('"', 1)
        if '""' in s:
            return (-1.67, 0.77) if '\n' in s else (-2.13, 0.45)
        if '"' in after:
            return -2.15, 1.36
        if before.endswith('\\'):
            if after.startswith(','):
                return -0.48, 0.27
            if after.startswith((')', '>', '}', ';')):
                return -0.74, 0.11
            return -1.09, 0.48
        if before.endswith('{'):
            return (-1.84, 1.04) if s[0].isspace() else (-2.70, 1.02)
        if before.endswith('='):
            return -2.33, 0.86
        if before.endswith(('(', '[')):
            return (-2.46, 1.30) if s[0].isspace() else (-1.95, 1.10)
        if before.endswith((':', ',')):
            return -1.95, 1.65
        if after.startswith(':'):
            return -1.00, 0.94
        if '\n' in after:
            return -1.02, 1.22
        if after.startswith(','):
            return -1.98, 2.15
        if after.startswith((')', '}', ']', ';')):
            return -1.90, 1.86
        if after.startswith(('.', '!', '?')):
            return -1.24, 1.39
        if before.endswith(('.', '!', '?')):
            return -1.48, 1.70
        if after and any(c.isalpha() for c in after):
            return (-2.76, 1.29) if after[0].isupper() else (-1.61, 0.45)
        return (-2.07, 1.83) if after else (-2.56, 2.03)
    if '“' in s and any(c.isalpha() for c in s):
        return -2.65, 1.23
    if '“' in s and s.endswith('“'):
        return (-2.34, 1.49) if s[0].isspace() else (-1.75, 1.29)
    if '“' in s or '”' in s:
        return (-1.01, 1.55) if '\n' in s else (-1.66, 1.64)
    if '„' in s:
        return -0.94, 0.59
    if '″' in s:
        return -1.36, 0.04
    if any(c in s for c in '«»'):
        return -0.59, 0.69
    return -0.37, 0.33


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, None, 0.0)
    _, position, last_quote, density = carry
    density *= 0.939413  # Exponentially decaying count: 16-token time scale.
    s = prefix.token_strings[-1]
    value = 0.0
    if any(c in QUOTES for c in s):
        recent = 0.0
        if last_quote is not None:
            gap = position - last_quote
            recent = 1 / math.sqrt(1 + gap / 3)
        context = 0.64 * recent + 0.26 * math.log1p(density)
        if position == 0:
            context += 0.85
        base, attenuation = strength(s)
        value = base + attenuation * context
        weight = 1.0
        if '"' in s and s.split('"', 1)[0].endswith('\\'):
            weight = 0.15
        elif any(c.isalpha() for c in s):
            weight = 0.3
        elif not any(c in s for c in '"“”'):
            weight = 0.5 if '″' not in s else 0.0
        density += weight
        if weight >= 0.5:
            last_quote = position
    elif '\\\\' in s:
        value = 0.45
    return (doc, position + 1, last_quote, density), float(value)

