def _han(char):
    return "\u3400" <= char <= "\u9fff"


def _han_score(text):
    if "研究人员" in text:
        return 2.0
    if "研究生" in text:
        return 1.3
    if "研究" in text:
        return 7.0
    if "科研" in text:
        return 0.9
    if "探索" in text:
        return 1.4
    if "试验" in text or "試驗" in text:
        return 0.7
    if "分析" in text or "調查" in text or "调查" in text:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc:
        partial, han_tail = carry[1], carry[2]
    else:
        partial, han_tail = "", ""

    token = prefix.token_strings[-1].casefold()
    words = []
    for i, char in enumerate(token):
        if char.isascii() and char.isalpha():
            partial += char
        else:
            if i == 0:
                partial = ""
            elif partial:
                words.append(partial)
                partial = ""

    if partial:
        words.append(partial)
    word_score = 0.0
    for word in words:
        word_score = max(word_score, LEXICON.get(word, 0.0))
        for stem, value in WORD_STEMS.items():
            if word.startswith(stem):
                word_score = max(word_score, value)

    han_text = "".join(char for char in token if _han(char))
    han_score = max(_han_score(han_text), _han_score(han_tail + han_text[:1]))
    han_tail = token[-1] if token and _han(token[-1]) else ""
    return (doc, partial, han_tail), float(max(word_score, han_score))

