programs.sol:
"""Detect closing punctuation and the word family 'test'.

The last punctuation mark is the main cue. Packed operators and opening
marks modify its strength; newlines and following commas usually weaken it.
Previous-token variables, indentation, escaped math delimiters, and HTML
entities provide small context corrections. Other text receives zero. This
is a surface-pattern approximation, not a vocabulary table or model replica.
The lexical cues include test/testing forms and the Chinese characters 试/試.
"""
import re

READS = ()
BASE = {')': 1.30, '）': 1.25, ']': 0.90, '}': 0.75,
        ';': 0.58, '；': 0.63}
OPERATORS = set('.:;!?%*+-&|=>')


def punctuation(s):
    q = s.strip()
    if not q:
        return 0.0
    last = q[-1]
    newline = '\n' in s or '\r' in s
    value = BASE.get(last, 0.0)
    if last in ')）':
        opening = any(c in q for c in '([{')
        operators = len(set(q[:-1]) & OPERATORS)
        value += 0.95 * min(operators, 2)
        if set(q) <= set('()'):
            if '(' in q:
                value = 0.84 if q.count(')') == 1 else 1.55
            elif len(q) > 1:
                value = 1.05
        elif opening:
            value += 0.75
        if newline:
            value = max(0.10, value - 1.05)
            if '.' in q:
                value -= 0.50
            if s.count('\n') > 1:
                value -= 0.15
    elif last == ']':
        value -= 0.45 if '[' in q else 0.0
        value += 0.60 if any(c in q for c in '.:?>') else 0.0
        value -= 0.85 if newline else 0.0
    elif last == '}':
        value += 0.20 if s.startswith(' ') else 0.0
        value -= 0.45 if '{' in q else 0.0
        if newline:
            value = 0.48
    elif last in ';；':
        if ')' in q:
            value = -0.15 if newline else 0.28
        elif newline:
            value = 0.05
    elif '@' in q:
        value = 0.87 if '(' in q or '[' in q else 1.18
        if q.count('@') > 1:
            value = 0.60 if s.startswith(' ') else 1.0
    elif any(c in q for c in ')]}'):
        if last == '(':
            value = 0.70 if ')' in q else 0.57
        elif last == '[':
            value = 1.17
        elif last == '{':
            value = 0.80 if q.startswith('}') else 0.20
        elif last == '\\':
            value = 0.40
        elif last == ',':
            value = 0.20 if '}' in q else -0.05
        elif last == '=':
            value = -0.20
    return value


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        previous, tail = carry[1:]
    q = s.strip().lower()
    if q in ('test', 'tests'):
        value = 0.74
    elif q in ('testing', 'tested', 'tester', 'testers', '试', '試'):
        value = 0.52
    elif re.fullmatch(r'[/_.-]tests?', q):
        value = 0.37 if q.startswith('/') else 0.60
    elif not any(c.isalnum() for c in s):
        value = punctuation(s)
    else:
        value = 0.0
    if not any(c in s for c in '\n\r'):
        if q in (')', ']', '}') and tail.endswith('\\'):
            value = 0.35
        elif q == ')':
            variable = previous.strip().lstrip('(')
            if (len(variable) == 1 and variable.isascii()
                    and variable.isalpha()):
                value = 1.10
            elif previous.strip().isdigit():
                value = 1.25
        elif q == '}' and re.search(r'\n[ \t]*$', tail):
            value = 1.10
        elif q == ';' and re.search(r'&(?:#[\w]+|[a-zA-Z]+)$', tail):
            value = 0.06
    return (doc, s, (tail + s)[-80:]), float(value)

