    return None, 0.0

programs.sol:
"""Detect the completion of a 'by' expression and some split-word endings.

The large negative signal is chiefly on the second half of expressions such
as 'by means', 'by default', and 'step by step'. It also recognizes
the final 'of' in common multiword by-expressions and weakens the signal
when an article or modifier intervenes. Articles after 'by' instead
get a small positive value. A second, orthographic response occurs inside
Cyrillic words after ы, especially when the next piece is one consonant.
Continuations after other Cyrillic vowels or Latin y get weaker negatives.
Only two preceding tokens are retained; document boundaries clear them.
"""

READS = ()

# Common bare complements of 'by': manner, method, rule, or repeated unit.
BY_EXPRESSIONS = {
    'way': -4.8,
    'hand': -4.6,
    'parts': -4.8,
    'means': -3.8,
    'step': -3.3,
    'side': -3.5,
    'phone': -3.9,
    'heart': -3.6,
    'reason': -3.6,
    'product': -3.7,
    'products': -3.7,
    'reference': -3.3,
    'virtue': -3.3,
    'nature': -3.2,
    'default': -2.9,
    'name': -2.8,
    'law': -2.7,
    'day': -3.0,
    'night': -2.5,
    'telephone': -2.7,
    'weight': -2.8,
    'chance': -2.6,
    'force': -2.4,
    'using': -2.1,
    'definition': -2.1,
    'term': -2.1,
    'contrast': -2.8,
    'comparison': -2.1,
    'contradiction': -2.0,
    'design': -2.1,
    'email': -2.1,
    'line': -1.6,
    'section': -1.6,
}


# Other conventional classes of bare 'by' complements.
TRANSPORT = {
    'air', 'boat', 'bus', 'car', 'foot', 'mail', 'rail', 'road', 'sea', 'train',
}
REASONING = {
    'analogy', 'assumption', 'convention', 'construction', 'example',
    'implication', 'use',
}
CRITERIA = {
    'category', 'column', 'country', 'date', 'id', 'key', 'kind', 'letter',
    'number', 'part', 'row', 'rows', 'size', 'state', 'subject', 'title',
    'type', 'value', 'word',
}
TIME_UNITS = {'hour', 'week', 'month', 'year'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        previous, before = carry[1:]
    p = previous.lower()
    word = token.strip().lstrip('-_').lower()
    value = 0.0

    if p.endswith('by'):
        if word in BY_EXPRESSIONS:
            value = BY_EXPRESSIONS[word]
            if token.startswith('-') and word in {'step', 'reference'}:
                value -= 0.9
        elif word in TRANSPORT:
            value = -2.3
        elif word in REASONING:
            value = -2.1
        elif word in CRITERIA:
            value = -1.8
        elif word in TIME_UNITS:
            value = -2.5
        elif word.endswith(('self', 'selves')):
            value = -2.1
        elif word in {'now', 'far'}:
            value = -1.9
        elif word == before.strip().lstrip('-_').lower() and word:
            value = -2.3
        elif word in {'a', 'an', 'some', 'these', 'those', 'this', 'that'}:
            value = 0.24
        elif word in {'the', 'his', 'her', 'their', 'our', 'my', 'your'}:
            value = 0.14
        elif word in {'one', 'zero'} or word.isdigit():
            value = -0.7
        elif word in {'choosing', 'doing', 'employing'}:
            value = -1.2
        elif token and token[0].isalpha():
            value = -1.4
        elif word.endswith('ing'):
            value = -0.3
        elif word.isalpha():
            value = -0.15
        elif token.isspace():
            value = -0.22

    elif before.lower().endswith('by') and word == 'of':
        # 'by means of', 'by way of', 'by virtue of'.
        if p.strip() in {'means', 'way', 'virtue'}:
            value = -1.25
        elif p.strip() == 'weight':
            value = -0.7

    elif before.lower().endswith('by') and word in BY_EXPRESSIONS:
        # A modifier/article can intervene: 'by applicable law', 'by the way'.
        value = 0.2 * BY_EXPRESSIONS[word]

    elif p.endswith('ы'):
        if token and '\u0400' <= token[0] <= '\u04ff':
            length = len(p.strip())
            if length >= 4:
                value = -0.05
            elif len(token) == 1:
                value = -3.6 if length == 1 else -2.0
                if token == 'ч':
                    value -= 2.5 if length == 1 else 1.7
                elif token in 'др':
                    value -= 0.8
            else:
                value = -2.3 if length == 1 else -1.2
                if len(token) > 2:
                    value += 0.25
        elif token.startswith(' '):
            value = -0.12

    elif p.endswith('y') and token and token[0].isalpha():
        value = -0.25
    elif p.endswith(tuple('аеёиоуэюя')):
        if token and '\u0400' <= token[0] <= '\u04ff':
            value = -0.12

    return (doc, token, previous), float(value)

