"""layers.0.mlp.down_proj:781 -- a 'by + bare noun' detector, plus Russian word-split detector.

Negative on the word right after English 'by' when it is a bare noun with no article
("by way", "by hand", "by means", "by step", "by default"), and on a Russian word fragment
that continues a token ending in 'ы' ("обы|чно", "испы|тывать"). Otherwise about 0.
"""

READS = ()

# Nouns that make "by X" an idiom with no article: strongest response.
IDIOM_NOUNS = set("way hand means step side day night name default parts phone contrast definition reference using".split())
ARTICLES = set("the a an his her their its my our your this that these those some any many all such".split())


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if prefix.document_ids[-1] != (prefix.document_ids[-2] if len(prefix.document_ids) > 1 else None):
        prev = ""
    word = _word(cur)
    if _word(prev) == "by" and word.isalpha():
        if word in IDIOM_NOUNS:
            return None, -3.0
        if word not in ARTICLES:
            return None, -0.5
        return None, 0.0
    if prev.endswith("ы") and cur[:1].isalpha() and not cur.startswith(" "):
        return None, -1.5
    return None, 0.0

"""Component layers.0.mlp.down_proj:782 -- a "bare verb after a non-third-person subject" detector.

It fires on a verb in base form (the present tense as used with I, we, you, they, or a plural
noun: "they receive", "people who have", "we make", "you go", "I think"), strongest after
"they" and "who". It stays near zero on -s, -ed, -ing and -ly forms, on "to + verb", on verbs
after "he/she/it", and on the verb after a modal (will/would give a small value).

The program looks at the word just before the current word, skipping negation and adverbs
("they often develop"), and within one document only.
"""

READS = ()

# How strongly a subject word before a bare verb makes it fire (means over the training data).
SUBJECT = {"they": 1.8, "who": 1.6, "we": 0.9, "you": 0.85, "i": 0.7, "that": 0.6, "which": 0.3}
# Plural nouns that do not end in -s, and other plural subjects.
PLURAL_WORDS = {"people", "children", "men", "women", "data", "both", "many", "others", "these", "those", "several"}
# Words ending in -s that are not plural nouns.
NOT_PLURAL = {"this", "is", "was", "has", "does", "its", "his", "us", "always", "perhaps", "thus", "yes", "unless", "less", "across"}
# Function words, which are never verbs here.
FUNCTION = set("""the a an and or but of in on at for with as by from is are was were be been being am has had
this these those it its his her their our my your there here then than so if when while because also just not no
all some any more most very too only even still now can will would may might must should could does did to
what which who how where why up out into about over after before under between through each every other such
same both few many much that they we you i he she them us me him one like per more less""".split())
# Irregular past-tense verbs, which are not base forms.
PAST = set("""made found began felt sent got took gave saw went came thought knew said told became left kept held
brought built bought caught taught led fell grew drew wrote ran sat stood won lost paid met set put read""".split())
# Base-form verbs that end in -s, -ed, -ing or -ly.
BASE_WITH_ENDING = {"need", "feed", "bring", "apply", "rely", "reply", "supply", "focus", "access", "process",
                    "address", "discuss", "imply", "exist", "speed", "proceed", "succeed", "exceed"}
MODALS = {"can", "could", "will", "would", "must", "may", "might", "should", "shall", "cannot", "to"}
# Words skipped when looking back from a verb to its subject.
SKIP = {"not", "t", "don", "also", "always", "often", "usually", "already", "never", "really", "just",
        "still", "all", "both", "generally", "typically", "currently", "only", "now"}


def is_bare_verb(word):
    """A lowercase word that can be a base-form verb."""
    if not word.isalpha() or not word.islower():
        return False
    if word in FUNCTION or word in PAST:
        return False
    if word in BASE_WITH_ENDING:
        return True
    if word.endswith(("ly", "ed", "ing")):
        return False
    return not (word.endswith("s") and not word.endswith("ss"))


def is_plural_noun(word):
    if word in PLURAL_WORDS:
        return True
    return word.isalpha() and word.endswith("s") and len(word) > 3 and word not in FUNCTION and word not in NOT_PLURAL


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings]
    t = prefix.position
    doc = prefix.document_ids
    # the current token must be a word that starts with a space, i.e. a whole word
    if not prefix.token_strings[t].startswith(" ") or not is_bare_verb(words[t]):
        return None, 0.0
    # walk back over negation and adverbs, staying inside this document
    j = t - 1
    while j > 0 and (words[j] in SKIP or words[j].endswith("ly")) and doc[j - 1] == doc[t]:
        j -= 1
    if j < 0 or doc[j] != doc[t]:
        return None, 0.0
    prev = words[j]
    if prev in MODALS:
        return None, 0.2 if prev in ("will", "would") else 0.0
    if prev in SUBJECT:
        return None, SUBJECT[prev]
    if is_plural_noun(prev):
        return None, 0.4
    return None, 0.0

"""layers.0.mlp.down_proj:784: a word detector for two kinds of mathematical vocabulary.

It fires on the word the current token belongs to, so a word split into pieces
("diffeo" + "morphism") counts once, at the piece that ends it.

Negative on abstract structure talk:
  strongest on transformation(s), mapped, equivalence, symmetry, functor, canonical;
  weaker on map, mapping, define(d), denote, operator, representation, correspond,
  linear, matrix, space, rotation, invariant, morphism-type words (homomorphic...).

Positive (number theory and proof talk):
  strongest on contradiction, divides/divisor, primes, integers, gcd, discriminant;
  weaker on prime, integer, degree, minimal, maximal, boundary, remainder, modulo.

"see" is positive when it is a proof aside ("let me see", "we can see"), weak after "to".

Everything else predicts 0. Context beyond the previous word is ignored.
"""
import re

READS: tuple[str, ...] = ()

STRUCTURE_STRONG = {"transformation", "transformations", "transforms", "transform", "mapped", "functor",
                    "equivalence", "symmetry", "symmetric", "canonical", "multiplication", "invert",
                    "permutation", "permutations", "embedding", "convolution", "rewrite", "defined"}
STRUCTURE = {"map", "maps", "mapping", "mappings", "define", "defines", "definition", "denote", "operator",
             "operators", "representation", "representations", "represent", "represents", "represented",
             "correspond", "corresponds", "corresponding", "correspondence", "equivalent", "rotation",
             "rotations", "rotate", "rotated", "linear", "continuous", "matrix", "matrices", "space",
             "spaces", "pace", "expressed", "express", "invariant", "tensor", "conjugate", "projection",
             "substitution", "decomposition", "consider", "multiply", "multiplied", "homomorphism",
             "quotient", "manifold", "metric", "inverse", "basis", "reflection"}
STRUCTURE_SUFFIX = ("morph", "morphism", "morphic", "orphism", "isms", "iance", "ometric")

DIVISIBILITY_STRONG = {"contradiction", "contradictory", "contrad", "divides", "divide", "divisor", "divisors",
                       "divis", "primes", "integers", "gcd", "discriminant", "discrimin", "dividing"}
DIVISIBILITY = {"integer", "prime", "degree", "degrees", "minimal", "maximal", "boundary", "dimension",
                "characteristic", "remainder", "absolute", "numerator", "denominator", "division", "singular",
                "div", "ord", "deg", "numerical", "fractional", "modulo", "residue", "determinant",
                "coefficients"}
DIVISIBILITY_SUFFIX = ("licity",)

PROOF_LEAD = {"let", "me", "us", "we", "can"}


def value_of(word):
    if word in STRUCTURE_STRONG:
        return -0.75
    if word in STRUCTURE or word.endswith(STRUCTURE_SUFFIX):
        return -0.33
    if word in DIVISIBILITY_STRONG:
        return 0.6
    if word in DIVISIBILITY or word.endswith(DIVISIBILITY_SUFFIX):
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    word, previous = carry if carry is not None else ("", "")
    piece = prefix.token_strings[-1]
    if word and re.fullmatch(r"[A-Za-z]+", piece):
        word = word + piece
    else:
        previous = word.lower() or previous
        word = piece.strip() if re.fullmatch(r"\s*[A-Za-z]+", piece) else ""
    value = value_of(word.lower())
    if word.lower() == "see":
        value = 0.7 if previous in PROOF_LEAD else 0.15
    return (word, previous), float(value)

programs.sol:
"""A spelling approximation to a detector for the syllable 'em'.

Bare 'em' is strongest, short em-ending fragments next, and longer
continuations weaker. Case, leading spaces and script affect the strength.
Several familiar word families refine this pattern; 'satisf-' is negative.
The bare fragment 'em' also depends on whether it continues an unfinished
word: beginnings and capitalized words are stronger than lowercase endings.
Only word-boundary, capitalization and ASCII/non-ASCII state is carried;
unrelated small responses are not captured.
"""
READS = ()
VOWELS = frozenset('aeiou')


def spelling_value(raw):
    word = raw.strip().strip('._-/<>():,;!"\'`[]{}')
    s = word.lower()
    spaced = raw.startswith(' ')
    if s == 'em':
        if word.isupper():
            return 4.9
        if word[0].isupper():
            return 3.8
        return 3.0 if spaced else 4.5
    if s in {'ém', 'êm'}:
        return 1.6
    if s.endswith('ем'):
        if s == 'ем':
            return 2.2
        if len(s) == 3:
            return 0.4 if s[0] in 'ардяъи' else 2.1
        return 0.35 if len(s) <= 5 else 0.0
    if s.startswith('satisf'):
        return -1.0 if s.endswith(('action', 'ying')) else -0.5
    if 'em' not in s:
        return 0.0
    if s in {'them', 'dem', 'rem', 'item'}:
        return 0.8 if s == 'item' else 1.4
    if s.startswith(('seem', 'member', 'element', 'empty', 'semp')):
        return 0.0
    if s in {'blem', 'blems'}:
        return 0.15
    if s.endswith('em'):
        onset = s[:-2]
        if not onset.isascii():
            return 0.4
        if len(s) == 3:
            if onset in 'aou':
                return 0.8
            return 3.1 if spaced else 3.5
        if len(s) == 4:
            if onset.endswith('r'):
                return 0.7
            return 1.0 if VOWELS.intersection(onset) else 2.7
        return 0.5 if len(s) == 5 else 0.0
    # Plural syllable fragments retain some of the strong ending response.
    if s.endswith('ems') and len(s) <= 5:
        return 0.4 if VOWELS.intersection(s[:-3]) else 2.4
    if s.startswith('stem'):
