    if s.startswith('sem'):
        return 1.4 if len(s) <= 5 else 0.9
    if s.startswith(('memor', 'membr', 'templat', 'chem')):
        return 0.8
    before, after = s.split('em', 1)
    if len(before) > 2:
        return 0.0
    if before in {'d', 'r'} or (not before and after.startswith('ent')):
        return 0.15
    if before == 'th' and len(after) <= 2:
        return 1.5
    if after == 'y':
        return 0.5
    if len(after) > 2:
        return 0.3
    return 1.3 if not before else 0.6


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        in_word, capitalized, ascii_word = False, False, True
    else:
        _, in_word, capitalized, ascii_word = carry
    value = spelling_value(raw)
    if raw == 'em':
        if not in_word:
            value = 5.2
        elif not ascii_word:
            value = 3.8
        else:
