"""Long horizontal spacing and repeated separator marks, not ordinary words.

Long space runs evoke a negative signal, strongest around 20 spaces.
Tabs have a similar, wider-spacing response; short spacing can be positive.
Blank-line tokens use their longest horizontal span, with a weaker response
when a newline is present.  Repeated punctuation separators also go negative.
These are empirical length curves, omitting word-specific and context effects.
"""
READS = ()


def space_signal(n):
    if n <= 7:
        return -0.02 if n == 3 else (0.12 if n >= 4 else 0.0)
    if n <= 11:
        return -0.22 * (n - 7)
    if n <= 18:
        return -1.35 - 0.115 * (n - 12) + (0.32 if n == 15 else 0.0)
    if n >= 100:
        return -1.0
    if n >= 60:
        return -1.6
    return -max(1.1, 2.01 - 0.026 * max(0, n - 24)) + (
        0.30 if n % 4 == 3 else 0.0
    )


def horizontal_signal(text):
    spaces, tabs = text.count(' '), text.count('\t')
    nbsp = text.count('\xa0')
    if nbsp:
        if nbsp >= 8:
            return -1.05
        if spaces + nbsp >= 8:
            return -0.88
        return -0.37 if nbsp >= 7 else -0.04
    if not tabs:
        return space_signal(spaces)
    if not spaces:
        if tabs >= 5:
            return -max(1.4, 1.97 - 0.07 * (tabs - 5))
        return (0.0, 0.01, -0.78, -1.40, -1.88)[tabs]
    width = spaces + 4 * (tabs - 1)
    if width <= 3:
        return 0.13
    if width <= 7:
        return -0.02 if width == 5 else -0.23
    if width <= 11:
        return -1.1 if width <= 9 else -1.41
    return -min(2.15, 1.41 + 0.14 * (width - 11))


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = 0.0
    if text and text.isspace():
        # A token can cover several blank lines: do not add their indentations.
        line = max(text.split('\n'), key=lambda s: len(s.expandtabs(4)))
        value = horizontal_signal(line)
        if '\n' in text or '\r' in text:
            value = min(0.0, value * 0.80)
            if line.count(' ') == 15 and '\t' not in line:
                value = -1.28
            if line.count('\t') == 2 and not line.count(' '):
                value = -0.34
    else:
        mark = text.strip()
        if len(mark) >= 10 and mark[0] in '-._=~*#' and len(set(mark)) == 1:
            n = len(mark)
            value = -min(1.0, 0.13 * (n - 8))
            if mark[0] in '_=~*#':
                value *= 0.5
            if n > 24 and mark[0] != '.':
                value *= 0.35 if n >= 40 else 0.65
            elif n >= 48:
                value *= 0.65
            if '\n' in text:
                value *= 0.75
    return None, float(value)

