"""Comment openings and decorative punctuation, not comment contents.

The strongest negative response is to C-style block-comment openings;
ordinary tokens get zero. Smaller responses mark line comments, triple
quotes, and text separators. Whitespace, line starts and document starts
change the strength; nearby repeated block openings are weaker. Marker
state distinguishes comment-line stars and closing triple quotes. This is
a heuristic, not a full code parser.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, line, in_block, quote, last_block = 0, '', False, None, -10000
    else:
        _, position, line, in_block, quote, last_block = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    spaced = token.startswith((' ', '\t'))
    newline = '\n' in token
    blank_line = token.count('\n') > 1
    # Numbered source listings and diff signs may precede indentation.
    line_start = not line.strip(' \t+-0123456789')
    value = 0.0

    if '/*' in s and not s.startswith('//'):
        if s.startswith('/**/*'):
            value = -2.6  # recursive filename wildcard, not a comment
        elif s.startswith('/*.'):
            value = -5.1
        elif s.startswith('/*!'):
            value = -6.5 + 0.85 * newline
        elif s.startswith('/**'):
            stars = len(s[1:]) - len(s[1:].lstrip('*'))
            if stars > 2:
                value = -6.6 - 1.0 / (1 + position / 4)
            else:
                value = (-5.25 - 0.33 * line_start - 0.2 * spaced
                         + 1.2 * newline + 1.9 * blank_line
                         - 0.8 / (1 + position / 64))
                if position == 0:
                    value = -6.36 if newline else -8.1
        elif s.startswith('/*'):
            value = (-7.57 - 0.64 * line_start - 0.1 * spaced
                     + 1.4 * newline - 1.36 * spaced * newline
                     + 1.0 * blank_line - 2.27 / (1 + position / 16))
            if position > 0:
                # Repeated nearby block openings are weaker than the first.
                value += 0.5 if position - last_block <= 48 else -0.4
            if position == 0:
                value = -17.0
                if newline:
                    value = -12.04 if '\r' in token else -12.45
                if blank_line:
                    value = -7.8
        else:
            value = -5.5  # opening merged with a brace, as in JSX
    elif '<!--' in s:
        value = -4.5 - 1.0 / (1 + position)
    elif '(*' in s and not any(c.isalnum() for c in s):
        value = -1.25
    elif '"""' in s or "'''" in s:
        if quote:
            value = -0.75 if newline else -1.0
        else:
            value = -1.75 if line_start else -1.05
            if newline:
                value += 0.45
        if blank_line:
            value = -0.4
        if position == 0:
            value = -2.2
    elif ('//' in s and '://' not in s
          and not any(c.isalnum() for c in s)):
        if '-' in s:
            value = -2.3
        elif len(s) > 3 and set(s) == {'/'}:
            value = -1.6
        elif s.startswith('///'):
            value = -0.75 if line_start else -0.5
        else:
            value = -1.3 if line_start else -1.05
            if s.startswith(('"', "'", ')')):
                value = -0.85
        if newline:
            value = -0.35
        if position == 0 and not spaced:
            value = -0.22 if newline else -2.32
    elif s == '#':
        value = (-0.8 if spaced else -0.58) if line_start else -0.18
        if newline:
            value = -0.1
        if position == 0:
            value = -0.15 if spaced else -1.55
    elif s.startswith('#') and s[1:].isalpha():
        if s[1:] in {'if', 'ifdef', 'ifndef'}:
            value = -1.35
        else:
            value = -0.2 if s[1:] == 'include' else -0.65
    elif s == '*':
        if line_start:
            value = -0.5 if in_block and spaced else -0.2 if spaced else -0.1
        if newline:
            value = -0.17 if spaced else -0.05
    elif s == '**':
        value = -0.64 if spaced or line_start else -0.17
        if newline:
            value = -0.15 if spaced else 0.0
    elif len(s) >= 3 and len(set(s)) == 1 and s[0] in '-=_#*~+!':
        length = len(s)
        if s[0] == '-':
            value = -min(1.05, 0.25 + 0.025 * length)
        elif s[0] == '=':
            value = -min(1.2, 0.25 + 0.05 * length)
        elif s[0] == '#':
            value = 0.08 if length < 8 else -min(1.6, 0.1 * length)
        elif s[0] == '*':
            value = -min(1.3, 0.15 * length)
        else:
            value = -0.6
        if newline:
            value *= 0.8
    elif len(s) > 4 and s.startswith(('#=', '*-')):
        value = -2.3
    elif '<?' in s:
        value = -1.2
    elif s in ('·', '··', '【', '】【'):
        value = -0.95 if '【' in s else -0.3 * len(s)

    # Maintain only a short line suffix and delimiter state.
    if ('/*' in token and not s.startswith(('//', '/*.', '/**/*'))):
        in_block = True
        last_block = position
    if '*/' in token:
        in_block = False
    for delimiter in ('"""', "'''"):
        if token.count(delimiter) % 2:
            if quote == delimiter:
                quote = None
            elif quote is None:
                quote = delimiter
    line = (line + token).replace('\\n', '\n').rsplit('\n', 1)[-1][-80:]
    state = (doc, position + 1, line, in_block, quote, last_block)
    return state, float(value)

