'''Comment openers (layer 0, MLP down_proj, component 788).

The component pushes the residual stream strongly negative when the current token opens a
comment or a comment-like banner in code or markup:
  * C block-comment openers "/*" (strongest, about -9); doc comments "/**" (about -5)
  * HTML comment opener "<!--" (about -4)
  * line-comment markers "//" and "///" (about -1.2)
  * hash comments "#" (about -0.5)
  * docstring quotes (about -1.2)
  * decorative separator runs such as "=====", "-----", "/////" (about -1.3)
  * ML-style "(*" openers (about -1.4) and runs of middle dots (about -0.8)
  * the leading star of a block comment's body, " *" and "**" (about -0.3 to -0.6)
Every other token gives 0. The value depends on the token alone, not on its context.
'''

READS = ()


def _value(s):
    if s.startswith("/**"):
        return -5.0
    if s.startswith("/*"):
        return -9.0
    if s == "<!--":
        return -4.0
    if s.startswith("//"):
        return -1.2
    if s == "#":
        return -0.5
    if s == "**":
        return -0.6
    if s == "*":
        return -0.25
    if s == "(*":
        return -1.4
    if s == "\u00b7\u00b7":
        return -0.8
    if s in ('"' * 3, "'" * 3):
        return -1.2
    if len(s) >= 4 and len(set(s)) == 1 and s[0] in "=-#*~":
        return -1.3
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(_value(prefix.token_strings[-1].strip()))

