    if token.startswith("//"):
        return None, -1.5
    if token.startswith(('"""', "'''")):
        return None, -1.4
    if token.startswith("#"):
        if set(token) == {"#"} and len(token) >= 3:
            return None, -0.35
        if token == "#":
            return None, -0.9
        return None, -0.7
    if token.startswith("*"):
        return None, -0.75 if token.startswith("**") else -0.45

    punctuation = token.rstrip(" \t\r\n")
