"""Local spelling fragments, especially a lateral L after C/K.

Short L-initial fragments respond positively after C/K-like letters and
less after L/R or a vowel.  Adverb -ly is positive, particularly after
ordinals, time words, and -ward.  Noun-to-adjective -ion + al is positive;
mod + ul and U-L after D/R are negative.  These are spelling rules, not
word-meaning recognition.  Two structural closing tags and the raw UTF-8
continuation byte B2 have separate small rules.  Unmatched text stays near
zero.  Only the previous token is retained; documents reset that state.
"""
import re

READS = ()
LATERALS = 'lлλلल'
VOWELS = 'aeiouаеиоуыэюяαεηιουω'
ORDINALS = {
    'first', 'second', 'third', 'fourth', 'fifth',
    'sixth', 'seventh', 'eighth', 'ninth', 'tenth',
}
TIME_WORDS = {'hour', 'day', 'week', 'month', 'year', 'night'}
UTF8_BYTE_B2 = 110  # Vocabulary token for the single byte b'\xb2'.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, token)
    s, stem = token.lower(), previous.strip().lower()
    p = previous[-1:].lower()

    if prefix.token_ids[-1] == UTF8_BYTE_B2:
        char = prefix.text_prefixes[-1][-1:]
        if char == '\ufffd':
            return carry, 0.25
        return carry, 0.43 if '\u4e00' <= char <= '\u9fff' else 0.14
    if token == '</think>':
        return carry, 0.113
    if token == '</tool_response>':
        return carry, -0.114

    initial_l = bool(s and s[0] in LATERALS)
    vowel_l = bool(len(s) > 1 and s[0] in VOWELS and s[1] in LATERALS)
    if not (initial_l or vowel_l):
        return carry, 0.0006
    long = len(s) > 4
    short_previous = max(0.0, 4.0 - len(stem)) / 3.0
    value = 0.015 * initial_l - 0.016 * long + 0.183 * (s == 'л')
    value -= 0.045 * s.endswith('s')
    value -= 0.081 * (len(s) > 1 and s[1] in 'ei' and s.endswith('n'))
    value -= 0.143 * s.endswith(('ic', 'ck'))
    value += 0.05 * (s.endswith('y') and s != 'ly')

    if p in ('c', 'с'):
        value += 0.41 + 0.15 * short_previous - 0.187 * vowel_l - 0.143 * long
    elif p in ('k', 'к', 'κ', 'ك', 'क'):
        value += 0.237 + 0.093 * short_previous - 0.131 * vowel_l - 0.125 * long
        value += 0.165 * (len(s) == 1)
    elif p in ('g', 'г', 'γ', 'p', 'b', 'п', 'б'):
        value += 0.085 - 0.066 * vowel_l
    elif p in ('s', 'σ'):
        value += 0.055
    elif p in ('l', 'л', 'λ', 'ل'):
        value -= 0.027 + 0.162 * short_previous
    elif p in ('r', 'р', 'ρ'):
        value -= 0.029 + 0.132 * short_previous
    elif p in ('d', 'д', 'δ'):
        value -= 0.033 + 0.132 * short_previous
    elif p and p in VOWELS:
        value -= 0.024

    match = re.search(r'[a-z]+$', stem)
    word = match.group() if match else ''
    if s == 'ly':
        value += 0.255 + 0.298 * (word in ORDINALS)
        value += 0.29 * (word in TIME_WORDS) + 0.116 * word.endswith('ward')
    if s == 'al' and word.endswith('ion'):
        value += 0.203
    if vowel_l and s[0] in ('u', 'у') and p in ('d', 'д', 'r', 'р'):
        value -= 0.132
    if s.startswith(('ul', 'уль')) and stem.endswith(('mod', 'мод')):
        value -= 0.243
    return carry, float(value)

