"""Approximate a spelling-pattern detector dominated by the zero in '20'.

The response occurs inside arbitrary numbers, not only dates. '21' and '30'
give smaller pulses; '31', '40', and '50' give faint ones. Separators weaken
rather than always eliminate the response, as in '2.0'. The main pulse weakens
later in a document, in digit-heavy text, and inside longer numeric strings;
a preceding extra 2 boosts it. Small rules cover 2nd, O after 2, and the
initial definite article. Other token-specific variations are left at zero.
"""
import math

READS = ()
DIGITS = frozenset('0123456789')
ARTICLE_START = {'The': 0.63, ' the': 0.56, ' The': 0.47, 'the': 0.25}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, before, digit_count = 0, '', '', 0
    else:
        _, position, previous, before, digit_count = carry
    value = 0.0
    if position == 0:
        value = ARTICLE_START.get(token, 0.0)
    elif previous == '2' and token == '0':
        value = 3.29 - 0.10 * math.log1p(position)
        value -= 0.40 * digit_count / (position + 1)
        if before in DIGITS:
            value -= 0.24
        if before == '2':
            value += 0.48
    elif (previous, token) in (('2', '1'), ('3', '0')):
        value = 0.84 - 0.028 * math.log1p(position)
        if before == '2':
            value += 0.18
    elif previous == '2' and token == 'nd':
        value = 0.54  # ordinal second, written 2nd
    elif previous in ('2', '₂') and token.strip() == 'O':
        value = (0.65 if previous == '₂'
                 else 0.47 if token == ' O' else 0.76)
    elif previous == '3' and token == '1':
        value = 0.22
    elif token == '0':
        if previous == '4':
            value = 0.14
        elif previous == '5':
            value = 0.08
        elif before == '2':
            if previous in ('.', ' '):
                value = 0.66
            elif previous in (',', '-'):
                value = 0.37
            elif previous in (':', '/'):
                value = 0.15
            elif previous == '\\xa':  # e.g. the byte escape \\xc2\\xa0
                value = 0.83
        elif before == '3' and previous == '.':
            value = 0.24
    digit_count += token in DIGITS
    carry = (doc, position + 1, token, previous, digit_count)
    return carry, float(value)

