CJK_RANGES = ((0x2E80, 0x9FFF), (0xAC00, 0xD7AF), (0xF900, 0xFAFF), (0x20000, 0x2FA1F))


def is_cjk(word):
    return any(any(lo <= ord(ch) <= hi for lo, hi in CJK_RANGES) for ch in word)


