    """Print the program's prediction for a few example tokens."""
    for token in [" the", " of", " peasant", " atrocities", "merce", "1", ",", "博彩"]:
        print(repr(token), step(None, _Fake(token), {})[1])


class _Fake:
    def __init__(self, token):
        self.token_strings = [token]


if __name__ == "__main__":
    main()

