"""Approximate a response to ASCII quotes and grammatical apostrophe endings.
Opening string delimiters are stronger than closing quote-punctuation pairs.
Recent/repeated marks are weaker, while early-document quotes are stronger.
Braces, assignments, semicolons and colons provide string-syntax evidence.
Doubled escapes and Chinese opening book-title brackets also respond.
Letter contexts distinguish apostrophe elision and prime notation.
Small unrelated token-specific responses are left at a near-zero baseline.
"""
import math

READS = ()
APOSTROPHE_ENDINGS = {'s': .76, 't': .86, 're': .72, 'm': .91,
           've': .99, 'll': .87, 'd': .85}
REPEAT = {
    'bare': (.57, .46, .22, .06),
    'spaced': (.08, .22, .19, .15),
    'ending': (.22, .22, .16, .10),
    'syntax': (.21, .17, .10, .06),
}


def quote_form(s):
    t = s.lstrip()
    if '《' in t:
        return .95, None, None
    if '\\\\' in t:
        return (1.0 if any(q in t for q in "\"'") else .72), None, None
    if not t or not any(q in t for q in "\"'"):
        return (-.10 if t in ('”', '’') else .002), None, None
    q = '"' if '"' in t else "'"
    head, tail = t.split(q, 1)
    if '\\' in head:
        return (-.12 if tail else .02), None, None
    if tail.startswith(q):
        return 0., None, None
    if head in ('{', '['):
        return -.03, None, None
    if head:
        base = .65 if head == '(' else .77 if head == '=' else .33
        if q == "'":
            base -= .16
        return base, q, 'syntax'
    if not tail:
        if t != s:
            return (.68 if q == '"' else .61), q, 'spaced'
        return (.89 if q == '"' else .74), q, 'bare'
    if q == "'" and tail in APOSTROPHE_ENDINGS:
        return APOSTROPHE_ENDINGS[tail], q, 'ending'
    if tail[0] in ',:;)]}.!?>' and not tail.startswith(('./', '../')):
        return (.28 if t != s else -.03), None, None
    return (.33 if tail[0] in '\r\n' else .70), q, 'syntax'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', {'"': 0, "'": 0}, {}, 0)
    doc, pos, previous, counts, last, syntax = carry
    s = prefix.token_strings[-1]
    value, q, kind = quote_form(s)
    p = previous.strip()
    if q:
        if counts[q]:
            gap = pos - last[q]
            band = 0 if gap < 4 else 1 if gap < 16 else 2 if gap < 64 else 3
            value -= REPEAT[kind][band]
        early = 1 / math.sqrt(pos + 1)
        repeated = min(counts[q], 8) / 8
        syntax_evidence = min(syntax, 8) / 8
        assignment = p.endswith((':', '=', '=>'))
        if kind == 'bare':
            value += 1.14 * early - .11 * repeated + .06 * syntax_evidence
            value -= .11 * (counts[q] % 2)
            if q == "'" and p.lower() in ('l', 'd', 'j', 'c', 's', 'qu'):
                value += .26  # apostrophe elision
            if q == "'" and p in ('F', 'B', 'U', 'D', 'L', 'R'):
                value += .53  # prime notation / cube moves
        elif kind == 'spaced':
            value += .69 * early + .16 * syntax_evidence + .12 * assignment
        elif kind == 'ending':
            value += .42 * early - .22 * repeated + .08 * syntax_evidence
            if s == "'t" and p.lower() in ('can', 'won', 'shan'):
                value -= .31
            if s == "'s" and p.lower() == 'here':
                value += .31
        else:
            value += .31 * early + .15 * assignment
    if pos == 0 and s in ('"', "'"):
        value = 3.97 if s == '"' else 2.96
    for mark in counts:
        if mark in s:
            counts[mark] += s.count(mark)
            last[mark] = pos
    syntax += int(any(c in s for c in '{}=;') or s.endswith(':'))
    return (doc, pos + 1, s, counts, last, syntax), float(value)

