VOWELS = set('aeiouyаеёиоуыэюя')
VOWEL_PATTERN = '[aeiouyаеёиоуыэюя]'


def spelling_response(s, previous):
    if not s.isalpha():
        return 0.0
    word = s.lower()
    if word[0] not in VOWELS:
        return 0.0

    consonant_prefix = bool(previous) and not any(
        c in VOWELS for c in previous.lower())
    if consonant_prefix:
        if previous.isupper():
            context = 1.0 if len(previous) == 1 else 0.13
        elif previous.istitle():
            context = 0.55
        else:
            context = 0.55 if len(previous) == 1 else 0.28
    elif len(previous) == 1 and previous.isupper():
        return 0.26 if len(word) > 1 and not s.isupper() else 0.03
    else:
        context = 0.10 if not previous else 0.06
        if len(previous) > 3:
            context = 0.0

    groups = re.findall(VOWEL_PATTERN + '+', word)
    first_gap = len(re.match(VOWEL_PATTERN + '+([^aeiouyаеёиоуыэюя]*)', word)[1])
    if len(groups) == 2:
        if first_gap == 1:
            if len(word) == 3:
                strength = 0.50 if word.endswith('e') else 1.19
            else:
                strength = 0.74 if len(word) == 4 else 0.39
        else:
            if len(word) == 4:
                strength = 0.44 if word.endswith('e') else 0.72
            else:
                strength = 0.30
    elif len(groups) >= 3:
        strength = 0.25
    elif len(word) == 1:
        return -0.20 if consonant_prefix else 0.0
    elif len(word) == 2:
        strength = 0.09 if previous.isupper() else -0.07
    else:
        strength = 0.29
    return context * strength


def response(s, previous):
    scale = 1.0 if s.isascii() else 0.4
    return scale * spelling_response(s, previous)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    tail = re.search('([A-Za-zА-Яа-яЁё]+)$', token)
    return (doc, tail[1] if tail else ''), float(value)

