            return -1.0 if length == 2 and coda != 'c' else -0.2
        if HOOK in marks:
            return -0.65 if single and not coda else -0.15
        if single and not coda:
            return -1.4 if vowel == 'u' and HORN in marks else -0.7
        return -0.1
    if recent and single and not coda and HORN in marks:
        return -0.5
    if recent and single and not coda and CIRCUMFLEX in marks:
        return -0.4 if vowel == 'o' else 0.1
    if length <= 3 and single and not coda:
        if DOUBLE_ACUTE in marks:
            return -0.8 if vowel == 'u' else -0.3
