    marks = {c for c in decomposed if ud.combining(c)}
    base = ''.join(c for c in decomposed if not ud.combining(c))
    syllable = re.fullmatch(r'([^aeiouy]*)([aeiouy]+)([^aeiouy]*)', base)
    if not syllable:
        return 0.0
