        if coda == 'ng' and vowel in {'a', 'o', 'u'}:
            return 0.8 if onset else 1.3
        if coda == 'nh' and vowel in {'a', 'i'}:
            return 1.0
        if coda in {'n', 'm'}:
            return 0.3 if onset else 0.9
        if not coda and vowel not in {'i', 'u', 'y', 'ou', 'ue'}:
            return 0.6 if onset else (1.5 if vowel == 'ay' else 1.0)
    elif fragment:
        if consonants and word in {
            'ang', 'ong', 'ung', 'anh', 'inh', 'ay', 'ao', 'au'
        }:
            if previous == 'zh' and word == 'ong':
                return 1.0
            return 0.5 if len(previous) == 2 else 0.15
        return {'ang': 0.1, 'ung': 0.1, 'ong': 0.2,
                'anh': 0.25, 'inh': 0.07, 'ay': 0.06}.get(word, 0.0)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, age = ('', 100) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    hint = vietnamese_hint(token)
    recent = hint or age < 16
    boundary = token[:1].isspace() or not previous or not previous[-1].isalnum()
    if token in TAGS:
        value = TAGS[token]
    elif boundary and word in GRAMMAR:
        enabled = recent or not word.isascii() or word == 'trong'
        value = GRAMMAR[word] if enabled else 0.0
    elif boundary and word in NEUTRAL:
        value = 0.0
    else:
