    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    if token == '%':
        value = -4.7
        if '\n' in raw:
            value = -2.3 if raw.count('\n') >= 2 else -3.3
    elif '%' in raw:
        value = -3.6 if raw.endswith('%') else -2.7
        if raw.count('\n') >= 2 or '%).' in raw:
            value = -2.1
    elif token in {'％', '٪', '﹪'}:
        value = -3.3
    elif word in {'percent', 'percentage', 'percentages'}:
        value = -1.7 if word == 'percent' else -1.5
        if not raw.startswith(' ') or token[0].isupper():
            value += 0.5
    elif token == '率':
        value = -0.6
    elif token in {'百分之', '占'}:
        value = -1.25
    elif token == '?' and '\n' not in raw:
        value = -0.36 if raw.startswith(' ') else -0.18
    else:
        value = 0.0
    return None, value

