    (('namespace',), 2.1),
    (('news', 'note', 'night', 'noise'), 1.95),
    (('network', 'natur', 'normally'), 1.1),
    (('needle', 'net'), 1.9),
    (('number',), 0.75),
    (('numer',), 1.4),
    (('new', 'now'), 1.05),
    (('need',), 1.3),
    (('name', 'next', 'near', 'native', 'nice', 'notation'), 1.4),
    (('notice', 'novel', 'november'), 1.5),
    (('necess',), 1.8),
    (('normal',), 1.95),
    (('nation',), 2.3),
    (('north',), 2.5),
    (('nodes',), 1.4),
    (('node',), 2.1),
)
NEGATIVE_N_WORDS = {
    'never', 'neither', 'nothing', 'nobody', 'none', 'negative',
    'nicht', 'nunca', 'nonetheless', 'nevertheless',
}
N_FUNCTION_WORDS = {'na', 'ne', 'nie', 'noch', 'nous', 'não', 'nostro'}
N_SUFFIXES = {'nd', 'nt', 'ng', 'ns', 'nc', 'ness', 'ning', 'nce', 'ncy',
              'nder', 'naire'}
NOT_AFTER_AUXILIARIES = (
    ({'do', 'does', 'did', 'can', 'could'}, 0.0),
    ({'may', 'might', 'would'}, 0.3),
    ({'will', 'should', 'must', 'have', 'has', 'had'}, 0.63),
    ({'is', 'are', 'was', 'were', 'am', 'be', 'been', "'s", "'m", "'re"}, 0.9),
)
KANA_N = {'な': 1.6, 'に': 0.95, 'ぬ': 2.0, 'ね': 2.7, 'の': -0.07,
          'ナ': 1.3, 'ニ': 1.1, 'ヌ': 2.0, 'ネ': 2.7, 'ノ': 2.2}
MANDARIN_N_INITIAL = set('拿那哪奶南难難耐嫩尼牛农農弄呢念脑腦')
CHINESE_N_WORDS = {'国家', '正常', '必要', '不要', '不', '没', '无', '無', '非',
                   '没有', '沒有', '不是', '名称', '需要', '全国', '新闻', '九'}


def latin_n_strength(token, word, previous):
    lower, upper = word.lower(), word[0].isupper()
    strength = (1.9 if upper else 1.3) if len(word) == 1 else 2.25 + 0.65 * upper
    for starts, value in N_FAMILIES:
        if lower.startswith(starts):
            strength = value + 0.2 * upper
            break
    if word.islower() and lower in N_FUNCTION_WORDS:
        strength = 1.3
    if lower in NEGATIVE_N_WORDS:
        strength = 0.85
    elif lower == 'non':
        strength = 1.35
    elif lower == 'no':
        strength = 1.55 + 0.35 * upper
    elif lower == 'null':
        strength = 1.2
    elif lower == 'not':
        strength = 1.65 if upper or not token.startswith(' ') else 1.25
        if token == ' not':
            previous_word = previous.strip().lower().replace('’', "'")
            for auxiliaries, value in NOT_AFTER_AUXILIARIES:
                if previous_word in auxiliaries:
                    strength = value
                    break
