        strength = 1.3  # The plural of the letter N.
    if token == word and word.islower() and lower in N_SUFFIXES:
        strength = 0.25
    if lower == 'name' and previous.endswith('{"'):
        strength = 1.95  # JSON field name.
    if token.startswith('/'):
        strength += 0.8  # N at the start of a path segment.
    if token.startswith('.') and len(word) == 1:
        strength += 1.1
    if lower.startswith('nation') and upper:
        strength += 0.4
    if word.isupper() and len(word) > 1:
        strength += 0.25
