        if word.islower() and len(word) <= 4 and lower not in {
                'name', 'new', 'node', 'next', 'now', 'null', 'not', 'num', 'npm'}:
            strength = -0.3 if previous[-1].lower() == 'n' else 0.55
        elif word.isupper() and previous[-1].isupper():
            strength *= 0.5  # Continuing an acronym rather than a new word.
    return strength


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    carry = (doc, token)
    word = token.lstrip(' \t\r\n_./([{\'"`\\-=+,:;@#$%<>!~*')
    lower = word.lower()
