        return carry, -0.06 if previous == '9' else -0.73
    if token == 'n' and previous.endswith('\\'):
        return carry, -0.22 if previous.endswith('\\\\') else 0.15
    if token == '\\n':
        return carry, -0.23
    if token.strip() in {'!=', '!==', '≠', '~', '~~', '～'}:
        return carry, -0.8
