        strength = {'на': 1.7, 'не': 1.5, 'но': 0.95}.get(lower, 2.2)
        if token == word and previous and previous[-1].isalpha():
            strength = -0.3 if previous[-1].lower() == 'н' else 0.55
        if word == 'н' and token == word:
            strength = 0.1
        return carry, -float(strength + 0.4 * word[0].isupper())
    if word.startswith('الن'):
        return carry, -3.0
    if word.startswith('ن'):
        return carry, -2.2 if token != word else -0.8
    if word and word[0] in KANA_N:
        return carry, -KANA_N[word[0]]
    if word and word[0] in MANDARIN_N_INITIAL:
        return carry, -1.3
    if word in CHINESE_N_WORDS or word.startswith(('名', '新', '北', '网', '網')):
        return carry, -1.0
    return carry, -0.012

