"""Sensitivity / sensing / detection word detector for layers.0.mlp.down_proj:815.

Component 815 of layer 0's MLP down-projection is a "sense-of-sensitivity" feature: it
goes strongly negative on the current token when that token is a word about sensitivity
or sensing (sensitive, sensitivity, sensor, sensing), and more weakly on words about
detecting, monitoring, sensing-adjacent nouns and their foreign equivalents (敏, 感,
чувств, 감). Everywhere else it is about zero. The program looks only at the newest token
and predicts its activation: the more "sensitive" the word, the more negative.
"""

import re

READS = ()


def activation(word):
    w = word.strip().lower()
    if w == "敏" or "sensit" in w:
        return -5.0  # sensitive, sensitivity, -sensitive, 敏
    if re.fullmatch(r"sensors?|sensing", w):
        return -3.5  # sensor, sensors, sensing
    if "monitor" in w:
        return -2.0  # monitor, monitoring, monitored
    if "responsive" in w:
        return -1.8
    if "detect" in w:
        return -1.2  # detect, detector, detection, detected
    if re.fullmatch(r"senses?|sensory|sensation", w):
        return -1.0
    if w in ("感", "감", "delicate", "allergic", "alert", "probe", "awareness"):
        return -0.8  # sense/feel in Chinese and Korean, and near-synonyms
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(activation(prefix.token_strings[-1]))

"""Kana runs: a negative response inside Japanese kana spellings.

Layer-0 MLP output channel 816 of Qwen3-1.7B (down_proj) is strongly negative on a
hiragana or katakana token that directly follows another kana token in the same document:
the inner syllables of a run of kana, such as the syllables of a katakana loanword or a
verb ending. Within such a run, grammatical hiragana particles (の は を が に と で も へ)
respond more weakly than single content syllables, and multi-character kana tokens weaker
still. A kana that starts a run after punctuation, spaces or other non-kanji text is
moderately negative; a kana right after a kanji is near zero; a kanji right after a kana
is mildly positive. Everything else is about zero.

The program reads only the current and previous token (no carried state), and treats the
first token of each document as having no previous token.
"""

import unicodedata

READS = ()

PARTICLES = set("のはをがにとでもへ")


def _is_script(s, script):
    return len(s) > 0 and all(unicodedata.name(c, "").startswith(script) for c in s)


def _kana(s):
    return _is_script(s, ("HIRAGANA", "KATAKANA"))


def _hiragana(s):
    return _is_script(s, ("HIRAGANA",))


def _kanji(s):
    return len(s) > 0 and all("一" <= c <= "鿿" for c in s)


def step(carry, prefix, upstream):
    # The first token of a document has no previous token in it.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    cur, prev = prefix.token_strings[-1], prefix.token_strings[-2]
    if _kana(cur):
        if _kana(prev):
            # Inside a kana run.
            if len(cur) > 1:
                return carry, -0.65
            if cur in PARTICLES:
                return carry, -1.0
            if _hiragana(cur):
                return carry, -2.5
            return carry, -1.8
        if _kanji(prev):
            return carry, 0.0
        # Start of a kana run after punctuation, spaces or other scripts.
        return carry, -0.3 if len(cur) > 1 else -0.8
    if _kanji(cur) and _kana(prev):
        # A kanji right after kana.
        return carry, 0.5
    return carry, 0.0

