        value = -1.0
    elif text.startswith('的') and han(text[1:]):
        tail = text[1:]
        if tail in {'是', '就是'}:  # copular clause, not a following noun
            value = -2.2
        elif tail in {'话', '話', '时候', '時候', '情况下'}:  # if/when
            value = -4.2
        elif tail in {'同时', '同時'} or tail.endswith(('中', '上', '下')):
            value = -5.3
        elif tail == '一':
            value = -4.9
        else:
            value = -6.8 if len(tail) == 1 else -7.1
    elif text == '之':
        value = -0.55
    elif text.startswith('之') and han(text):
        locative = len(text) == 2 and text[1] in '前后後中上下内外間间一'
        value = -1.0 if locative else -2.1
    elif text.endswith('的') and len(text) == 2 and not han(text[0]):
        value = -0.75
    elif text == 'の':
        value = -0.94
    elif text.startswith('の'):
        if han(text[1:]) or text == 'のこと':
            value = -5.5
        elif text in {'のお', 'のご'}:  # honorific noun prefix
            value = -4.7
        elif text in {'のは', 'のが', 'のも', 'のか',
                       'のある', 'のために', 'の方が'}:
            value = -2.7
        else:
            value = -1.2
    elif 'こと' in text:
        if text == 'こと':
            value = -1.3
        elif text.startswith('こと'):
            value = -0.7
        else:
            value = -3.3 if text.endswith('こと') else -2.3
    elif text in {'もの', 'ため', 'ために', 'よう'}:
        value = -0.65
    elif text.endswith(('るために', 'るのは', 'るのが', 'なのか')):
        value = -2.8
    elif text in {'について', 'における', 'に対して', 'により'}:
        value = -1.3
    elif text in {'의', 'của'}:  # Korean and Vietnamese genitive particles
        value = -0.75 if text == '의' else -1.0
    elif text in {'时', '時', '后', '後'}:
        value = -0.6
    elif han(text):
        value = 0.02 if len(text) == 1 else -0.2
        if previous in {'的', 'の', '之'}:
            value -= 0.45 if len(text) == 1 else 0.7
