DOTS = {"...", " ...", "..", " ..", "(...", "[...]", " [...]", "(..", "...("}
QUOTE = {" „", "„"}
THAN = {" than", "than", " Than", "Than"}
FIXED_THAN = {" rather", " other", " Rather", " none"}
WEAK_THAN = {" less", " greater"}
DASHES = {" —", "—", "——", " ——", " –", "–"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if ELLIPSIS_CHAR in tok:
        value = 2.2
    elif tok in THAN:
        before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
