            value = 0.1
        elif before in WEAK_THAN:
            value = 0.5
        else:
            value = 0.9
    elif tok in DOTS or tok in QUOTE:
        value = 0.7
    elif tok in DASHES:
        value = 0.5
    else:
        value = 0.0
    return carry, value

