"""Approximate the component's negative response to documentation boundaries.

Recognize C/Java documentation comments, C#/Rust triple-slash comments,
Python docstring openings, documentation tags, and Markdown headings. Line
and block state distinguish comment margins from multiplication; a preceding
function/class declaration identifies a docstring opening. Numeric line
prefixes are treated as source listings.
Ordinary text gets a near-zero prediction, not a learned token lookup.
"""
import re

READS = ()
DOC_TAGS = {
    'param': -0.68,
    'return': -1.92,
    'returns': -1.92,
    'brief': -3.0,
    'author': -2.05,
    'throws': -0.85,
    'see': -0.9,
    'description': -1.9,
}
DOC_LABELS = {'TODO', 'FIXME', 'Returns', 'Description', 'DESCRIPTION', 'Args'}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        line, last_line, block, first, previous = '', '', '', False, ''
    else:
        _, line, last_line, block, first, previous = carry
    s = token.strip()
    leading = bool(re.fullmatch(r'\s*[-+]?\s*\d*\s*', line))
    numbered = leading and any(c.isdigit() for c in line)
    newline = '\n' in token or '\r' in token
    value = -0.001

    if s == '/**':
        value = -8.9 if leading else -8.5
        if numbered:
            value = -7.4
        block, first = 'doc', True
    elif s == '/*!':
        value, block, first = -5.6, 'doc', True
    elif s.startswith('/**') and not s[3:].strip('*'):
        value, block, first = -3.0, 'plain', True
    elif s == '///':
        if newline:
            value = -1.1
        elif '<summary>' in last_line:
            value = -8.1
        elif '</summary>' in last_line:
            value = -6.1
        else:
            value = -2.9 if numbered else -4.3
    elif s.startswith('//'):
        value = -1.1 if len(s) > 8 else (-0.63 if leading else -0.4)
    elif s.startswith('/*'):
        value, block, first = -0.34, 'plain', True
    elif s.startswith('"""') or s.startswith("'''"):
        # A colon-ended declaration followed by quotes opens a docstring.
        declaration = leading and bool(re.search(
            r'\b(?:def|class)\b.*:\s*$', last_line
        ))
        if declaration:
            value = -2.2 if newline else -2.85
        else:
            value = -0.65 if token.startswith(' ') else -0.4
        if numbered:
            value *= 0.55
    elif s == '*' and token.startswith(' '):
        if leading or block:
            if newline:
                value = -0.7 if block == 'doc' else -0.4
            elif first and block == 'doc':
                value = -1.8 if numbered else -3.7
            elif block == 'doc':
                value = -1.25 if numbered else -1.75
            else:
                value = -1.0
            first = False
        else:
            value = 0.1
    elif s == '@':
        value = -0.74 if token.startswith(' ') else -0.17
    elif s in DOC_TAGS and previous.strip() in {'@', '\\'}:
        value = DOC_TAGS[s]
    elif s == 'summary' and not token.startswith(' '):
        if '///' in line:
            value = -3.75 if previous.strip() == '<' else -2.5
        else:
            value = -1.1
    elif s.startswith('#') and not s.strip('#'):
        if len(s) == 1:
            if token.startswith(' '):
                value = -0.66 if leading else -0.32
            else:
                value = -0.25 if leading else -0.1
        else:
            value = {2: -0.16, 3: -0.57}.get(len(s), -0.35)
    elif s in DOC_LABELS:
        value = -0.6
    elif s in {'@Override', 'Override', '#['}:
        value = -1.0 if s == '@Override' else -0.5

    if s and s != '*' and not s.startswith(('/*', '//')):
        first = False
    if '*/' in token:
        block, first = '', False
    # Also recognize escaped newlines in source embedded inside strings.
    text = (line + token).replace('\\n', '\n').replace('\\t', '\t')
    lines = re.split(r'\r\n|[\r\n]', text)
    if len(lines) > 1:
        last_line = lines[-2][-160:]
    line = lines[-1][-160:]
    return (doc, line, last_line, block, first, token), float(value)

