"""Layer-0 MLP component 821: the opener of a documentation comment.

The component goes strongly negative where a documentation comment begins:
  /**  (Javadoc / JSDoc opener)                    about -9
  /*!  (Doxygen opener)                            about -5.5
  ///  (C# / Rust doc-comment line, not the bare ///+newline token)  about -4
It stays negative on the lines inside a /** block: the star at the start of
each line is about -3.8 for the first few lines and about -1.5 after that.
Documentation tag words (summary, brief, return, param) are negative only
shortly after such an opener. Python docstring quotes are about -1.3, and
the ordinary comment markers (//, #, ###, @) about -0.5.
Everything else is about 0.

The program keeps a small state: whether we are inside a /** block and how
many tokens into it we are, and the position of the last doc opener. The
state resets at each new document.
"""

READS = ()

OPENERS = {"/**": -9.0, "/*!": -5.5}
MARKERS = {"//": -0.6, "###": -0.6, "#": -0.3, "@": -0.8}
TAGS = {"summary": -3.0, "brief": -2.3, "return": -1.2, "returns": -1.2, "Returns": -1.2, "param": -0.4}
NEAR = 40  # tokens after a doc opener in which a tag word counts


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    pos = prefix.position
    new_doc = pos == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        inside, count, last = False, 0, -1000
    else:
        inside, count, last = carry
    value = 0.0
    if token in OPENERS:
        value = OPENERS[token]
        inside, count, last = True, 0, pos
    elif token == "///":
        value = -1.2 if raw.endswith("\n") else -4.0
        if not raw.endswith("\n"):
            last = pos
    elif token == '"""':
        value = -1.3
    elif token == "*/":
        inside = False
    elif token == "*":
        if inside:
            value = -3.8 if count < 3 else -1.5
    elif token in TAGS:
        if pos - last <= NEAR:
            value = TAGS[token]
    elif token in MARKERS:
        value = MARKERS[token]
    if inside:
        count += 1
    return (inside, count, last), value

