READS = ()
HOOKS = {
    "useState", "useEffect", "useContext", "useRef",
    "useMemo", "useCallback", "useReducer",
}
FRONTEND = {
    "React", "JSX", "jsx", "typescript",
    "props", "Props", "className", "ClassName",
