    "toBe", "toEqual", "toStrictEqual", "toMatchSnapshot",
    "toBeFalsy", "toBeTruthy",
}


def opening(token, previous, react):
    left, right = token.split("{", 1)
    spaced = token[0].isspace()
    if "}" in right or left.endswith("}"):
        return 0.0
    if right.startswith("..."):
        return 1.9
    if left.endswith("}_"):
        return 0.3
    if left in ("^", "_"):
        return 0.6
    if left.endswith(("=", ">", "::", ".", "/", ":")):
        return 1.15
    if "${" in token:
        return 1.1 if "`" in token or react else 0.7
    command = re.search(r"\\([A-Za-z]+)\s*$", previous)
