    if any(root in token for root in AUTH_WORDS):
        return None, -1.0
    if any(root in token for root in ("validat", "acknowledg")):
        return None, -0.85
    if any(root in token for root in ("verif", "author")):
        return None, -0.7
    if "ident" in token:
        return None, -0.35
    if "permission" in token:
        return None, -0.35
    if "certif" in token or "approv" in token:
        return None, -0.3
    if "registr" in token or "login" in token:
        return None, -0.15
    if "commit" in token:
        return None, -0.2
    if any(word in token for word in CHINESE_CHECKING):
        return None, -0.8
    if "认" in token:
        return None, -1.0
    if "assert" in token or "affirm" in token:
        return None, -0.6
    if "увер" in token or "тверж" in token or "reconoc" in token:
        return None, -0.5
    return None, 0.0

programs.sol:
"""A token-shape approximation to a possessive / noun-modifier response.
Word-fused Chinese 的 and Japanese の are strongest; standalone markers and
English possessive 's are weaker. Japanese and Korean modifier endings get
smaller responses. These are morphological heuristics, not a grammatical parse.
English contractions need one previous token, reset at document boundaries.
"""
READS = ()
CONTRACTIONS = set('it he she that there here what who how where when let'.split())
PLURALS = set('men women children people'.split())
PERSONS = set('我 你 您 他 她 它 我们 你们 他们 她们 它们'.split())


def ending_response(s):
    if s == '的':
        return 2.1
    # The noun 目的 ('purpose') merely ends in the same character.
    if s.endswith('目的'):
        return 3.9 if s == '目的' else 2.2
    if s.endswith('的'):
        stem = s[:-1]
        if stem in PERSONS:
            return 5.0
        return 6.3 if any(c.isalnum() for c in stem) else 3.5
    if s == '的な':  # Japanese adjective-forming suffix.
        return 2.9
    if s.startswith('的'):
        return 1.1
    if s.endswith('もの'):  # Japanese 'thing', not possessive の.
        return 1.0
    if s == 'の':
        return 1.3
    if s.endswith('の'):
        return 1.8 if s in ('この', 'その', 'あの', 'どの', 'なの') else 4.7
    if any('\u3040' <= c <= '\u309f' for c in s):
        kanji = any('\u4e00' <= c <= '\u9fff' for c in s)
        # Polite forms, requests, and adverbial endings are weaker.
        if s.endswith(('です', 'ください', '下さい', 'しく', 'なく')):
            return 0.2
        if s.endswith(('ます', 'く')):
            return 0.8
        if s in ('よう', 'そう', 'どう', 'もう', 'くらい', 'ぐらい', 'いつ'):
            return 0.2
        if s.endswith(tuple('るうすつぶむぬぐいな')):
            return 0.8 if len(s) == 1 else (2.4 if kanji else 1.6)
        if s.endswith('た') and s not in ('また', 'あなた'):
            return 0.8 if len(s) == 1 else 1.6
    if any('\uac00' <= c <= '\ud7af' for c in s):
        if s.endswith('의'):  # Korean possession.
            return 1.0 if s == '의' else 2.8
        if s.endswith(('는', '한', '인', '된', '던', '할', '은', '른', '운')):
            return 0.6 if len(s) == 1 else 1.6
    # Secondary responses to code syntax and Chinese modifier particles.
    if s == '::' or s.endswith('>::'):
        return 1.05
    if s.endswith('</'):
        return 0.8
    if s in ('instanceof', '等', '地', '得', '之'):
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1].strip()
    if s in ("'s", '’s', "'S"):
        word = previous.lower()
        if word in CONTRACTIONS:
            value = -0.12
        else:
            value = 0.38 if word in PLURALS else 0.87
    else:
        value = ending_response(s)
    return (doc, s), value

programs.haiku:
"""Pre-nominal modifier particles: the word-final particle that attaches a modifier
(a possessive, genitive or attributive) to the noun that follows it.

It fires on the particle itself, the token just before the head noun:
- Chinese 的, strongest when attached to a word (市场的 "market's", 公司的 "company's",
  上的 "on the", 里的 "in the"); standalone 的 is weaker. After a personal pronoun
  (我的 "my") it is a bit weaker, and adverbial 真的 ("really") is weak.
- Japanese の attached to a word (年の, などの, さんの), weaker when standalone; attributive
  な attached to a word (大きな, 素敵な).
- English possessive 's after a noun (Thomas Mann's), but not the contraction 's of
  "That's", "There's", "Let's" and similar, which is ~0.
- The "::" path/scope operator (Rust, PHP, C++), a weaker genitive-like link.
Everything else predicts 0. The values are rough means of the component's activation
on training text, in the component's own units.
"""

READS = ()

PRONOUNS = {"我", "你", "他", "她", "它", "您", "我们", "你们", "他们"}
CONTRACTION_HOSTS = {"that", "there", "let", "he", "she", "it", "what", "who", "here",
                     "where", "how", "when", "why"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if tok == "的":
        value = 2.1
    elif tok.endswith("的"):
        if tok == "真的":
            value = 1.7
        elif tok[:-1] in PRONOUNS:
            value = 4.5
        else:
            value = 6.2
    elif tok in ("の", "な"):
        value = 1.3
    elif tok.endswith("の"):
        value = 3.5
    elif tok.endswith("な"):
        value = 2.1
    elif tok in ("'s", "’s"):
        value = 0.0 if prev in CONTRACTION_HOSTS else 1.0
    elif tok == "::":
        value = 1.1
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Recognize overt possessive/attributive linkers and a couple syntax markers.
Fused Chinese/Japanese linker tokens get stronger pulses; others default to zero."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "'s" in token or "’s" in token:
        return None, 0.9
    # A token ending in 的 often includes the noun/adjective it modifies;
    # these fused Chinese phrases are stronger than the standalone particle.
    if token.endswith("的"):
        return None, 5.4 if token != "的" else 2.2
    if "的" in token:
        return None, 2.2
    if token.endswith("の"):
        return None, 4.5 if token != "の" else 1.6
    if "の" in token:
        return None, 1.6
    if "ของ" in token:
        return None, 0.5
    # Code namespace and closing-markup delimiters have small responses too.
    if token.endswith("::") or token == "::":
        return None, 0.9
    if token == "</":
        return None, 0.7
    return None, 0.0

"""Use a probable inflectional -ing ending, excluding common lookalikes."""

READS = ()
UNINFLECTED_ING = {
    "string", "during", "according", "bring",
    "spring", "king", "morning", "ring",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(".,;:!?()[]{}\"'")
    if word.endswith("thing") or word in UNINFLECTED_ING:
        return None, 0.0
    return None, 0.72 if word.endswith("ing") else 0.0

programs.sol:
"""Approximate an x-spelling feature using only the newest two tokens.

The training responses were strongest for short spellings starting with x,
including byte escapes, and negative for short spellings ending in ex.
Isolated x and medial x are weaker. Length, leading punctuation, and a few
recognizable spellings refine these rules; they do not describe subject matter.
The previous spelling adds an immediate-token correction, especially for
joined letters. This carryover resets at document boundaries.
Unrecognized spellings have zero base response.
"""
import string
READS = ()


def current(text):
    if text.startswith('<') and text.endswith('>'):
        return 0.0, ''
    word = text.lstrip(string.whitespace + string.punctuation)
    lower = word.lower()
    n = len(word)
    if lower.startswith('x'):
        if n == 1:
            value = 0.74 if text == 'x' else 0.64
            if text.startswith(('-', '/', '.')):
                value = 0.96
            return value, 'x'
        if text.startswith('\\x'):
            return 2.4, 'escape'
        if set(lower) == {'x'}:
            return 4.6 / n, 'initial'
        # The markup-language abbreviation is weaker than other initial x's.
        if lower.startswith('xml'):
            return 1.45, 'initial'
        if n == 2:
            # xi is also the usual Latin spelling of the Greek letter.
            if lower[1] == 'i':
                return 2.4, 'initial'
            if lower[1] in 'aeoy':
                return 3.0, 'initial'
            return 3.75, 'initial'
        return 2.6 * (3 / n) ** 0.6, 'initial'
    if lower.endswith('ex'):
        if n == 2:
            value = -1.7 if word == 'ex' else -1.1
            if text[:1].isspace():
                value += 0.2
            elif text[:1] in string.punctuation:
                value = -0.7
            return value, 'ex'
        value = -1.05 if n <= 4 else -0.2
        if n == 3 and text[:1].isspace():
            value = -0.65
        return value, 'ex'
    if lower.endswith('x'):
        return -0.1, 'other_x'
    # The text-file abbreviation and the exc spelling are positive exceptions.
    if lower == 'txt':
        return 0.85, ''
    if lower.startswith('exc'):
        value = 1.55 if n <= 5 else 0.5
        return value, 'internal'
    if 'x' in lower:
        at = lower.index('x')
        if at == 1:
            scale = 0.8
            if lower.startswith('ex'):
                scale = 0.4
            elif lower.startswith('ox'):
                scale = 1.3
            return scale * (3 / n) ** 1.4, 'internal'
        return 0.06, 'internal'
    # Related cross-script spellings: Cyrillic eks/kh, Greek xi/chi, Arabic kha.
    if lower.endswith('екс'):
        return -0.9 if n <= 4 else -0.15, ''
    if word in ('х', 'Х', 'χ', 'Χ'):
        value = 0.5 if text[:1].isspace() or word.isupper() else 0.1
        return value, ''
    if word == 'ξ':
        return 0.95, ''
    if 'خ' in word:
        return 0.65, ''
    return 0.0, ''


def continuation(previous, text):
    if not previous or 'x' in text.lower():
        return 0.0
    if text.isascii() and text[:1].isalpha():
        return {'x': 0.8, 'ex': 0.3, 'other_x': 0.5,
                'initial': 0.2, 'internal': 0.05, 'escape': 0.0}[previous]
    if previous == 'escape' and text.isdigit():
        return -0.15
    if previous == 'x':
        if text.isdigit() or text == ' ':
            return 0.3
        return 0.06
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    value, kind = current(text)
    value += continuation(previous, text)
    if text == '\\x':
        kind = ''
    return (doc, kind), float(value)

"""Approximate a preference for short written forms of R and 'er'.

Recognize Latin/Cyrillic R and selected rhotic letters or syllables in other
scripts. Attenuate word-internal consonant clusters and acronym capitals;
give longer R-initial pieces a small response. Decode completed South Asian
ra letters when UTF-8 is split across tokens. Other shapes predict zero,
leaving weak, idiosyncratic whole-word responses unexplained.
"""
import string
import unicodedata

READS = ()
INDIC_RA = frozenset('रਰরৰરରரరರരර')  # South Asian letters named ra
STOPS = frozenset('bptdgkбптдгк')
VOWELS = frozenset('aeiouyаеёиоуыэюяαεηιουωάέήίόύώ')
PUNCTUATION = string.punctuation + '“”‘’«»'


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip(PUNCTUATION)
    # A split UTF-8 token may finish a letter without decoding on its own.
    if '�' in token:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in INDIC_RA:
            return None, 1.60
        return None, 0.0
    previous = ''
    if (len(prefix.token_strings) > 1 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2][-1:]
    boundary = spelling != token
    lower = previous.lower()

    if spelling in {'r', 'р'}:
        if token.startswith('\\'):
            value = 0.57  # carriage-return escape
        elif boundary:
            value = 0.89 if token[0] in './-' else 0.79
            if token[0] in '([_,=':
                value = 0.70
        elif lower == 'ъ':
            value = 1.30
        elif lower in STOPS:
            value = 0.40
        elif previous.isalpha():
            value = 0.58
        else:
            value = 0.74
    elif spelling in {'R', 'Р'}:
        if boundary:
            value = 0.78 if token[0] in '([_,/' else 0.92
        else:
            value = 0.53 if previous.isupper() else 0.96
    elif spelling == 'er':
        value = 0.90 if boundary else (0.50 if lower in VOWELS else 0.28)
    elif spelling == 'Er':
        value = 1.04 if boundary else 0.95
    elif spelling == 'ER':
        value = 0.96 if boundary else 0.37
    elif spelling in {'ér', 'är', 'ер'}:
        value = 0.54
    elif spelling == 'ор':
        value = 0.36
    elif spelling == 'ρ':
        value = 0.59 if lower in VOWELS else 0.34
    elif spelling == 'Ρ':
        value = 0.66
    elif spelling == 'ر':
        value = 0.97 if boundary else 1.22
    elif spelling == 'ร':
        value = 1.16
    elif spelling in INDIC_RA:
        value = 1.55
    elif spelling in {'尔', '爾'}:  # Mandarin er, also used in transliterations
        value = 1.02
    elif spelling in {'儿', '兒', '耳'}:  # Mandarin er
        value = 0.29
    elif spelling == 'ル':
        value = 0.43
    elif spelling in {'る', 'ラ'}:
        value = 0.17
    elif len(spelling) == 1 and unicodedata.normalize('NFKC', spelling) in 'rR':
        value = 0.60 if spelling.isupper() else 0.35
    elif len(spelling) == 2 and spelling.endswith('R') and spelling.isupper():
        value = 0.22  # R inside a short initialism
    elif spelling in {'ар', 'ار', 'ور', 'ير'}:
        value = 0.30  # short vowel-plus-R syllables
    elif boundary and len(spelling) > 1 and spelling[0] in 'rR':
        if len(spelling) == 2:
            value = 0.36 if spelling[-1].lower() in 'aou' else 0.10
        else:
            value = 0.06 if len(spelling) <= 4 else 0.02
    else:
        value = 0.0
    return None, value

programs.luna:
"""Approximate a sparse response to standalone r-like letters and pieces."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in {"r", "р", "ρ", "ル"}:
        return None, 0.85
    if token in {"er", "ér", "är", "-r"}:
        return None, 0.65
    return None, 0.0

programs.sol:
"""Lowercase fragments continuing capitalized words, especially names.

Familiar name parts raise the signal; grammatical endings, all-caps prefixes,
and long fragments lower it. This is a spelling heuristic, not recognition of
individual people or places. Spaces and punctuation end a word.
"""
READS = ()

GRAMMAR = frozenset((
    'ly', 'tion', 'tions', 'ation', 'ations', 'ment', 'ments', 'ness',
    'ity', 'ities', 'ally', 'ive', 'ively', 'able', 'ible', 'ous', 'ously',
    'ize', 'ized', 'izing', 'ism', 'ist', 'ists', 'ics', 'ical', 'ically',
    'ent', 'ence', 'ance', 'ency', 'ancy', 'ung', 'ungen', 'heit',
    'heiten', 'keit', 'keiten', 'schaft', 'schaften', 'lich', 'liche',
    'lichen', 'ischer', 'ische', 'ischen', 'ique', 'iques', 'eur', 'eurs',
    'ismus', 'ase', 'ases', 'ide', 'ides', 'ate', 'ates', 'ology', 'logy',
    'oma', 'omas', 'itis', 'osis',
))

NAME_ENDINGS = frozenset((
    'son', 'sen', 'man', 'mann', 'ton', 'ley', 'wood', 'well', 'worth',
    'field', 'ford', 'land', 'berg', 'burg', 'stein', 'ov', 'ova', 'ev',
    'eva', 'sky', 'ski', 'skiy', 'ovich', 'vich', 'ian', 'yan', 'ani',
    'ini', 'ino', 'elli', 'etti',
))

NAME_PARTS = frozenset((
    'bert', 'brecht', 'hard', 'ard', 'rich', 'rick', 'ric', 'mund', 'mond',
    'win', 'bald', 'ald', 'olf', 'ulf', 'wald', 'fried', 'ham', 'am',
    'ann', 'anna', 'ana', 'ina', 'ella', 'elle', 'ette', 'etta', 'ano',
    'ica', 'ika', 'ovich', 'vich',
))


def activation(word, token):
    stripped = token.strip()
    if token[:1].isspace() and stripped.isalpha():
        return -0.022 if stripped[0].isupper() else 0.003
    if not word or not token.isalpha() or not token[0].islower():
        return 0.0
    if not word[0].isupper():
        return -0.012 if token.isascii() else 0.0

    # The smaller non-ASCII signal is mainly Latin and Cyrillic spelling.
    if not token.isascii():
        if all('\u0400' <= c <= '\u04ff' for c in token):
            return 0.23
        if all(c.isascii() or '\u00c0' <= c <= '\u024f' for c in token):
            return 0.42
        return 0.04

    value = 0.76
    if word.isupper():
        value -= 0.22 if len(word) == 1 else 0.53
    if len(word) >= 6:
        value -= 0.27
    if len(word) >= 10:
        value -= 0.28
    if len(token) >= 4:
        value -= 0.16
    if len(token) >= 7:
        value -= 0.44
    if token in GRAMMAR:
        value -= 0.32
    value -= {'s': 0.25, 'ed': 0.48, 'ing': 0.36}.get(token, 0.0)
    if token in NAME_ENDINGS:
        value += 0.50
    if token in NAME_PARTS:
        value += 0.43
    if token[-1] in 'aeiouy':
        value += 0.11
    if not any(c in 'aeiouy' for c in token):
        value -= 0.14
    return max(0.0, value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = activation(word, token)
    for ch in token:
        word = word + ch if ch.isalpha() else ''
    return (doc, word), float(value)

programs.luna:
"""A small signal for subword continuations of capitalized words.

Layer 0 often gives a positive activation to later pieces of names and other
capitalized terms. Keep track of whether the current word began uppercase;
predict a modest positive value for its alphabetic continuation pieces.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        in_word, capitalized = False, False
    else:
        _, in_word, capitalized = carry

    value = 0.24 if (
        in_word and capitalized and token and token[0].isalpha()
    ) else 0.0

    for char in token:
        if char.isspace():
            in_word, capitalized = False, False
        elif char.isalpha():
            if not in_word:
                in_word, capitalized = True, char.isupper()
        elif char in "-'’":
            pass
        else:
            in_word, capitalized = False, False

    return (document, in_word, capitalized), float(value)
